insert into public.therapist_resources (slug, title, kind, summary, goal, audience, duration, body_md, fields, tags, created_at)
values
  ('weekly-boundaries-review-sheet', 'Weekly Boundaries Review Sheet', 'worksheet'::resource_kind, 'A weekly page for noticing where a client held, bent or dropped a limit they set.', 'Use it to help a client see which limits held and what got in the way of the rest.', array['Adults']::text[], '20 minutes weekly', 'Have the client fill it in before the session and read one entry aloud. Look for the situation that made a limit hard, not for a grade on the week. Ask what they would want to say differently next time. It works best when the limits were chosen by the client rather than suggested by others.', '[{"id": "f0", "type": "textarea", "label": "A limit I set this week"}, {"id": "f1", "type": "textarea", "label": "Where it held"}, {"id": "f2", "type": "textarea", "label": "Where it slipped, and what was happening"}, {"id": "f3", "type": "textarea", "label": "One sentence I could say next time"}]'::jsonb, array['boundaries', 'review', 'between sessions']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('decision-values-filter-sheet', 'Decision Values Filter Sheet', 'worksheet'::resource_kind, 'A sheet that runs one stuck decision through what the client says matters to them.', 'Use it to help a client weigh a choice against their own stated values.', array['Adults']::text[], '25 minutes', 'Ask the client to name a decision they keep circling, then to list three values in their own words. Each option is then read against each value. Expect some values to conflict; that is useful material for the session. The sheet does not pick the answer, the client does.', '[{"id": "f0", "type": "textarea", "label": "The decision I am stuck on"}, {"id": "f1", "type": "textarea", "label": "Three things that matter most to me here"}, {"id": "f2", "type": "textarea", "label": "How option one fits each one"}, {"id": "f3", "type": "textarea", "label": "How option two fits each one"}, {"id": "f4", "type": "textarea", "label": "The step I could take this week"}]'::jsonb, array['decision-making', 'values', 'planning']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('session-takeaway-card', 'Session Takeaway Card', 'worksheet'::resource_kind, 'A short card a client fills in at the end of a session so the main point goes home with them.', 'Use it to help a client leave with one idea and one action in their own words.', array['Adults']::text[], 'Five minutes at session end', 'Hand it over in the last few minutes and let the client write before you summarize, so you hear what actually landed. Compare their version with yours and be curious about the gap. Keep the card in the file or photograph it for the next session opener.', '[{"id": "f0", "type": "textarea", "label": "The main thing I want to remember"}, {"id": "f1", "type": "textarea", "label": "Something that surprised me today"}, {"id": "f2", "type": "textarea", "label": "One small thing I will try before we meet again"}, {"id": "f3", "type": "textarea", "label": "A question I still have"}]'::jsonb, array['session structure', 'homework', 'review']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('energy-leaks-and-refills-inventory', 'Energy Leaks and Refills Inventory', 'worksheet'::resource_kind, 'Two lists a client builds: what drains their day and what gives something back.', 'Use it to give a client a plain picture of where their energy goes during a week.', array['Adults']::text[], '25 minutes', 'Have the client fill both columns from a recent ordinary week, not an ideal one. Then look at timing: which leaks cluster before which refills. Avoid turning it into a should list; the aim is a map the client can adjust one small piece at a time.', '[{"id": "f0", "type": "textarea", "label": "Things that drained me this week"}, {"id": "f1", "type": "textarea", "label": "Things that gave something back"}, {"id": "f2", "type": "textarea", "label": "A leak I could shrink a little"}, {"id": "f3", "type": "textarea", "label": "A refill I could add or protect"}, {"id": "f4", "type": "textarea", "label": "Who or what could help with that"}]'::jsonb, array['energy', 'stress', 'planning']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('difficult-conversation-preparation-sheet', 'Difficult Conversation Preparation Sheet', 'worksheet'::resource_kind, 'A planning page for a conversation a client is dreading, from goal to first sentence.', 'Use it to help a client plan what they want from a hard conversation before they have it.', array['Adults']::text[], '30 minutes', 'Work through it in session and rehearse the opening line aloud. Help the client separate what they want to say from what they hope the other person will do, since only the first is in their hands. Save the page so you can debrief afterward.', '[{"id": "f0", "type": "textarea", "label": "Who I need to talk to and about what"}, {"id": "f1", "type": "textarea", "label": "What I hope comes out of it"}, {"id": "f2", "type": "textarea", "label": "Facts I want to state without blame"}, {"id": "f3", "type": "textarea", "label": "How I feel, in a sentence"}, {"id": "f4", "type": "textarea", "label": "What I will do if it goes badly"}]'::jsonb, array['communication', 'planning', 'assertiveness']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('thought-record-with-balanced-alternative', 'Thought Record With Balanced Alternative', 'cbt'::resource_kind, 'A seven-column style thought record ending in a balanced alternative thought.', 'Use it to walk a client from a hot thought to a more balanced one, step by step.', array['Adults']::text[], '20 minutes', 'Teach it in session with a recent, moderate situation before sending it home. Ask the client to rate belief in the thought before and after so they can see the shift, even a small one. Watch for a rewritten thought the client does not believe; go back to the evidence column.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "What I felt, and how strong (0 to 100)"}, {"id": "f2", "type": "textarea", "label": "The automatic thought"}, {"id": "f3", "type": "textarea", "label": "Evidence that supports the thought"}, {"id": "f4", "type": "textarea", "label": "Evidence that does not fit the thought"}, {"id": "f5", "type": "textarea", "label": "A more balanced thought, and how much I believe it"}]'::jsonb, array['thought record', 'automatic thoughts', 'core CBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('cognitive-distortion-detective-sheet', 'Cognitive Distortion Detective Sheet', 'cbt'::resource_kind, 'A sheet for spotting common thinking traps in a client''s own thoughts.', 'Use it to help a client name the thinking trap behind a thought and question it.', array['Adults']::text[], '20 minutes', 'Give the client a short list of traps in plain words and ask them to find one in each of three recent thoughts. Naming a trap is a way to step back from a thought, not proof that it is wrong. Invite them to write a question that would loosen the trap.', '[{"id": "f0", "type": "textarea", "label": "A thought that bothered me this week"}, {"id": "f1", "type": "textarea", "label": "Which thinking trap it sounds like"}, {"id": "f2", "type": "textarea", "label": "A question I could ask to test it"}, {"id": "f3", "type": "textarea", "label": "What I would tell a friend who had this thought"}]'::jsonb, array['thinking traps', 'distortions', 'core CBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('behavioral-experiment-planner', 'Behavioral Experiment Planner', 'cbt'::resource_kind, 'A page to turn a client''s prediction into a small test with a way to check the result.', 'Use it to help a client test a prediction in real life and compare it with what happened.', array['Adults']::text[], '25 minutes', 'Pick a prediction that is specific enough to check, and agree on what would count as the prediction being right. Plan the experiment in session and note what could go wrong and how the client will cope. Review the result together, including when it was mixed.', '[{"id": "f0", "type": "textarea", "label": "My prediction, and how sure I am (0 to 100)"}, {"id": "f1", "type": "textarea", "label": "The small experiment I will try"}, {"id": "f2", "type": "textarea", "label": "What I will look for"}, {"id": "f3", "type": "textarea", "label": "What actually happened"}, {"id": "f4", "type": "textarea", "label": "What I take from it"}]'::jsonb, array['behavioral experiment', 'evidence', 'core CBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('activity-and-mood-diary', 'Activity and Mood Diary', 'cbt'::resource_kind, 'An hourly or blocked diary linking what a client does with how they feel.', 'Use it to give a client and clinician real data on how activities and moods line up.', array['Adults']::text[], 'Ten minutes daily for a week', 'Start with a few blocks a day rather than every hour so it stays doable. Ask for a mood number and a quick note of what they were doing. In session, look for the activities that sit near better and worse moments and let the client draw the conclusion first.', '[{"id": "f0", "type": "textarea", "label": "What I was doing this morning, and my mood (0 to 10)"}, {"id": "f1", "type": "textarea", "label": "What I was doing this afternoon, and my mood (0 to 10)"}, {"id": "f2", "type": "textarea", "label": "What I was doing this evening, and my mood (0 to 10)"}, {"id": "f3", "type": "textarea", "label": "The activity that felt best or most meaningful"}, {"id": "f4", "type": "textarea", "label": "The activity I would change"}]'::jsonb, array['monitoring', 'behavioral activation', 'self-monitoring']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('worry-time-scheduling-sheet', 'Worry Time Scheduling Sheet', 'cbt'::resource_kind, 'A sheet for setting a daily worry period and parking worries until then.', 'Use it to help a client set aside a short daily worry period and postpone worries to it.', array['Adults']::text[], 'Ten minutes daily for two weeks', 'Agree on a time and place that is not near bedtime. During the day the client jots worries on the page and returns to what they were doing. At the worry period, ask which worries still feel live. Many clients find the list shorter than expected; some do not, and that is worth discussing.', '[{"id": "f0", "type": "textarea", "label": "The time and place I chose for worry time"}, {"id": "f1", "type": "textarea", "label": "A worry I noticed and postponed"}, {"id": "f2", "type": "textarea", "label": "What I did instead in the moment"}, {"id": "f3", "type": "textarea", "label": "At worry time: is it still a worry, and can I act on it?"}, {"id": "f4", "type": "textarea", "label": "One action I can take or let go of"}]'::jsonb, array['worry', 'scheduling', 'core CBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('values-compass-check-in', 'Values Compass Check-In', 'act'::resource_kind, 'A simple weekly check on how closely a client''s actions pointed toward what matters to them.', 'Use it to help a client compare a week of actions with the directions they say they value.', array['Adults']::text[], '20 minutes weekly', 'Ask the client to choose two or three life areas and name a value in each. Then they rate how closely the week matched and name one small action that would move it. Keep the tone curious. A low number is information, and it is not a verdict.', '[{"id": "f0", "type": "textarea", "label": "A life area and a value I chose"}, {"id": "f1", "type": "textarea", "label": "One thing I did this week that fit it"}, {"id": "f2", "type": "textarea", "label": "One thing that pulled me away"}, {"id": "f3", "type": "textarea", "label": "A small action for next week"}]'::jsonb, array['values', 'committed action', 'core ACT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('leaves-on-a-stream-practice-notes', 'Leaves on a Stream Practice Notes', 'act'::resource_kind, 'A guided defusion practice using leaves on a stream, with a notes page for afterward.', 'Use it to give a client a way to watch thoughts pass without following each one.', array['Adults']::text[], 'Ten minutes', 'Read the exercise slowly in session, then ask what it was like rather than whether it worked. Some clients find the image hard; invite a substitute such as clouds or a conveyor belt. Send home a short version and a place to note what they noticed.', '[{"id": "f0", "type": "textarea", "label": "The thoughts that floated by"}, {"id": "f1", "type": "textarea", "label": "What it was like to watch them go"}, {"id": "f2", "type": "textarea", "label": "A moment I got pulled onto a leaf"}, {"id": "f3", "type": "textarea", "label": "What I noticed when I stepped back"}]'::jsonb, array['defusion', 'mindfulness', 'core ACT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('willingness-dial-exercise', 'Willingness Dial Exercise', 'act'::resource_kind, 'A dial from unwilling to fully willing for clients to place on a hard but valued step.', 'Use it to help a client find how willing they are to feel discomfort for something that matters.', array['Adults']::text[], '20 minutes', 'Name a specific step the client cares about and ask where the dial sits today. Then ask what would move it one notch, not to the top. The number is not something to push. Talk through what discomfort they would be making room for and how they could carry it.', '[{"id": "f0", "type": "textarea", "label": "The step that matters to me"}, {"id": "f1", "type": "textarea", "label": "Where the dial sits today (0 to 10)"}, {"id": "f2", "type": "textarea", "label": "What would move it up one notch"}, {"id": "f3", "type": "textarea", "label": "The discomfort I would be making room for"}]'::jsonb, array['willingness', 'acceptance', 'core ACT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('hands-as-thoughts-metaphor-sheet', 'Hands as Thoughts Metaphor Sheet', 'act'::resource_kind, 'A brief metaphor in which held-up hands stand in for how thoughts crowd the view.', 'Use it to show a client the difference between holding thoughts and holding them at a distance.', array['Adults']::text[], '15 minutes', 'Have the client hold their hands over their eyes, then lower them to the lap. Ask what they could do and see in each position. The point is that the thoughts do not have to go anywhere; they can sit where the client can still act. Follow with the prompts.', '[{"id": "f0", "type": "textarea", "label": "What I could see with my hands over my face"}, {"id": "f1", "type": "textarea", "label": "What changed when I lowered them"}, {"id": "f2", "type": "textarea", "label": "A thought I tend to hold up close"}, {"id": "f3", "type": "textarea", "label": "One thing I could do with that thought resting in my lap"}]'::jsonb, array['metaphor', 'defusion', 'core ACT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('chessboard-and-pieces-self-practice', 'Chessboard and Pieces Self Practice', 'act'::resource_kind, 'A chessboard metaphor separating the observing self from thoughts and feelings.', 'Use it to help a client take an observer position toward their own thoughts and feelings.', array['Adults']::text[], '20 minutes', 'Draw or lay out a board with two teams of pieces standing for thoughts and feelings, and the board as the client. Ask which team they have been trying to beat. Point out that the board holds every piece and takes no side. Let them describe it in their own words.', '[{"id": "f0", "type": "textarea", "label": "The pieces I have been fighting"}, {"id": "f1", "type": "textarea", "label": "What has that fight cost me"}, {"id": "f2", "type": "textarea", "label": "What the board holds without taking sides"}, {"id": "f3", "type": "textarea", "label": "How I could act from the board today"}]'::jsonb, array['self-as-context', 'observing self', 'core ACT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('tipp-skills-practice-card', 'TIPP Skills Practice Card', 'dbt'::resource_kind, 'A card for practicing the TIPP skills to bring intense arousal down fast.', 'Use it to help a client practice a set of quick body-based skills before they need them.', array['Adults']::text[], '20 minutes', 'Practice each skill in session when the client is calm, such as cool water on the face or paced breathing, and check any health limits first. Then ask which one they would reach for and where they will keep the card. Note that the skills lower arousal; solving the problem comes after.', '[{"id": "f0", "type": "textarea", "label": "A time I felt very worked up"}, {"id": "f1", "type": "textarea", "label": "Which TIPP skill I want to try first"}, {"id": "f2", "type": "textarea", "label": "Where I will keep what I need for it"}, {"id": "f3", "type": "textarea", "label": "How my body felt before and after"}]'::jsonb, array['TIPP', 'distress tolerance', 'core DBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('wise-mind-check-in-sheet', 'Wise Mind Check-In Sheet', 'dbt'::resource_kind, 'A brief practice for checking what emotion mind, reasonable mind and wise mind say.', 'Use it to help a client find the place where feeling and reason both have a voice.', array['Adults']::text[], '15 minutes', 'Walk the client through a decision, asking what emotion mind says, what reasonable mind says, and what settles in the middle. Some clients need a breath or a minute of quiet before the third answer arrives. Do not supply it for them.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "What emotion mind says"}, {"id": "f2", "type": "textarea", "label": "What reasonable mind says"}, {"id": "f3", "type": "textarea", "label": "What wise mind says"}]'::jsonb, array['wise mind', 'core DBT', 'mindfulness']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('dear-man-request-rehearsal-sheet', 'DEAR MAN Request Rehearsal Sheet', 'dbt'::resource_kind, 'A fill-in script for making a request or saying no using the DEAR MAN steps.', 'Use it to help a client draft and rehearse an assertive request or refusal.', array['Adults']::text[], '25 minutes', 'Build the script in session and role-play it, taking the other person''s part with a few realistic pushbacks. Ask the client to keep the ask to one clear sentence. Remind them to plan for the other person saying no, since asking well does not guarantee the answer.', '[{"id": "f0", "type": "textarea", "label": "Describe the situation in facts"}, {"id": "f1", "type": "textarea", "label": "Express how I feel about it"}, {"id": "f2", "type": "textarea", "label": "Assert: what I am asking for or declining"}, {"id": "f3", "type": "textarea", "label": "Reinforce: what is in it for the other person"}, {"id": "f4", "type": "textarea", "label": "What I will do if they say no"}]'::jsonb, array['DEAR MAN', 'interpersonal effectiveness', 'core DBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('pros-and-cons-of-acting-on-urges-sheet', 'Pros and Cons of Acting on Urges Sheet', 'dbt'::resource_kind, 'A four-box sheet weighing acting on an urge against tolerating it, short and long term.', 'Use it to help a client see the short and long term of acting on or riding out an urge.', array['Adults']::text[], '20 minutes', 'Fill in all four boxes in session, including the real short-term payoffs of acting, since skipping them loses credibility. Encourage the client to keep the sheet where the urge tends to show up. If the urge involves risk to safety, follow your own plan; this sheet does not replace it.', '[{"id": "f0", "type": "textarea", "label": "The urge I am looking at"}, {"id": "f1", "type": "textarea", "label": "Pros of acting on it"}, {"id": "f2", "type": "textarea", "label": "Cons of acting on it"}, {"id": "f3", "type": "textarea", "label": "Pros of riding it out"}, {"id": "f4", "type": "textarea", "label": "Cons of riding it out"}]'::jsonb, array['pros and cons', 'distress tolerance', 'urges']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('self-validation-statements-sheet', 'Self-Validation Statements Sheet', 'dbt'::resource_kind, 'A sheet for writing validating statements a client can offer themselves.', 'Use it to help a client practice acknowledging their own feelings without judging them.', array['Adults']::text[], '20 minutes', 'Explain that validating does not mean approving of a behavior or agreeing with a thought; it means saying that the feeling makes sense given what happened. Draft three statements together and try them aloud. Clients who find this odd often warm to it with practice.', '[{"id": "f0", "type": "textarea", "label": "A feeling I had this week"}, {"id": "f1", "type": "textarea", "label": "What happened that made it make sense"}, {"id": "f2", "type": "textarea", "label": "A validating sentence I could say to myself"}, {"id": "f3", "type": "textarea", "label": "How it felt to say it"}]'::jsonb, array['validation', 'emotion regulation', 'core DBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('turning-toward-bids-tracker', 'Turning Toward Bids Tracker', 'couples'::resource_kind, 'A weekly tracker where both partners note small bids for attention and how they were met.', 'Use it to help partners notice small bids and how each of them responds.', array['Couples']::text[], 'One week', 'Each partner keeps a tally of bids they made and bids they noticed from the other. Bring both sheets to session and read one example from each. Expect partners to have missed some. The aim is to notice, not to keep score against each other.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a bid I made and how it was met"}, {"id": "f1", "type": "textarea", "label": "Partner A: a bid I noticed and how I responded"}, {"id": "f2", "type": "textarea", "label": "Partner B: a bid I made and how it was met"}, {"id": "f3", "type": "textarea", "label": "Partner B: a bid I noticed and how I responded"}, {"id": "f4", "type": "textarea", "label": "One thing we will each try next week"}]'::jsonb, array['bids', 'Gottman', 'connection']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('shared-goals-vision-sheet', 'Shared Goals Vision Sheet', 'couples'::resource_kind, 'A page where both partners write what they each want for the next year and merge a shared list.', 'Use it to help partners name what they want for the next year and find where they overlap.', array['Couples']::text[], '30 minutes', 'Partners first write separately, then share, then build a joint list. Point out the overlaps before the differences. Where goals conflict, note them for a later session rather than settling them on the spot.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I hope for us in a year"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I hope for us in a year"}, {"id": "f2", "type": "textarea", "label": "Where our hopes overlap"}, {"id": "f3", "type": "textarea", "label": "One shared goal we will start on this month"}, {"id": "f4", "type": "textarea", "label": "What each of us will do first"}]'::jsonb, array['goal setting', 'shared meaning', 'planning']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('softened-start-up-practice-cards', 'Softened Start-Up Practice Cards', 'couples'::resource_kind, 'Cards for turning a complaint into a gentle start with a feeling and a request.', 'Use it to help partners practice raising an issue without blame at the start.', array['Couples']::text[], '25 minutes', 'Take a mild complaint from each partner and rewrite it in the form of "I feel, about, and I need". Partners read them aloud, and the listener says what they heard. Slow the pace if either partner tenses. Use small issues first.', '[{"id": "f0", "type": "textarea", "label": "Partner A: my complaint, rewritten as I feel, about, I need"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I heard it"}, {"id": "f2", "type": "textarea", "label": "Partner B: my complaint, rewritten as I feel, about, I need"}, {"id": "f3", "type": "textarea", "label": "Partner A: how I heard it"}]'::jsonb, array['Gottman', 'communication', 'conflict']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('outside-stress-daily-talk-guide', 'Outside Stress Daily Talk Guide', 'couples'::resource_kind, 'A guide for a daily short talk where each partner listens to the other''s outside stress.', 'Use it to help partners give each other a place to talk about stress outside the relationship.', array['Couples']::text[], '20 minutes daily', 'Partners take turns for about ten minutes each on stress from work, family or other outside sources. The listener does not fix or advise unless asked, and shows interest and understanding. Debrief what helped and what did not.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a stress I want to talk about"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I heard and how I showed I was on their side"}, {"id": "f2", "type": "textarea", "label": "Partner B: a stress I want to talk about"}, {"id": "f3", "type": "textarea", "label": "Partner A: what I heard and how I showed I was on their side"}]'::jsonb, array['listening', 'support', 'Gottman']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('rituals-of-connection-planner', 'Rituals of Connection Planner', 'couples'::resource_kind, 'A planner where partners choose small daily and weekly rituals to keep connected.', 'Use it to help partners choose a few small rituals that keep them connected.', array['Couples']::text[], '25 minutes', 'Ask each partner to name a moment in their week that feels like closeness and then choose two rituals that fit a real schedule. Start small. Revisit them in a couple of weeks and drop any that feel like chores.', '[{"id": "f0", "type": "textarea", "label": "Partner A: a moment that feels close to me"}, {"id": "f1", "type": "textarea", "label": "Partner B: a moment that feels close to me"}, {"id": "f2", "type": "textarea", "label": "Our daily ritual"}, {"id": "f3", "type": "textarea", "label": "Our weekly ritual"}, {"id": "f4", "type": "textarea", "label": "How we will remember to do them"}]'::jsonb, array['connection', 'routines', 'Gottman']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('feelings-face-paper-plates-craft', 'Feelings Face Paper Plates Craft', 'kids'::resource_kind, 'Children decorate paper plates with faces for the feelings they know.', 'Use it to help a child put shapes and words on a handful of feelings through making them.', array['Children']::text[], '25 minutes', 'Let the child make a plate face for each feeling they pick, such as happy, mad, scared or calm. Ask when they last had that feeling. The parent joins in by making one of their own and naming when they felt it. If a child mentions being hurt or unsafe, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "A feeling I made a face for"}, {"id": "f1", "type": "textarea", "label": "When I felt that feeling"}, {"id": "f2", "type": "textarea", "label": "What my body did when I felt it"}, {"id": "f3", "type": "textarea", "label": "Something that helps me when I feel it"}]'::jsonb, array['emotion identification', 'art', 'children']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('calm-down-bottle-craft', 'Calm-Down Bottle Craft', 'kids'::resource_kind, 'Children make a glitter bottle to watch settle while they breathe.', 'Use it to give a child a hands-on cue for slowing down and breathing.', array['Children']::text[], '25 minutes', 'Help the child fill a clear bottle with water, glue and glitter, seal it well, and shake it. The child watches the glitter settle while breathing slowly. The parent learns to offer it as an invitation rather than a punishment. Keep it in a place the child can reach.', '[{"id": "f0", "type": "textarea", "label": "What color glitter I picked"}, {"id": "f1", "type": "textarea", "label": "What my mind looks like when the glitter is swirling"}, {"id": "f2", "type": "textarea", "label": "What I noticed as the glitter settled"}, {"id": "f3", "type": "textarea", "label": "When I could use my bottle at home"}]'::jsonb, array['self-soothing', 'sensory', 'children']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('helping-hands-support-drawing', 'Helping Hands Support Drawing', 'kids'::resource_kind, 'A child traces their hand and writes a helper on each finger.', 'Use it to help a child name people who help them and what those people do.', array['Children']::text[], '20 minutes', 'The child traces one hand and puts a helper on each finger, with a picture or a name. The parent adds one helper of their own and says what they do for the child. Notice children who list few helpers. If a child hints that someone is not safe, follow your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "A helper I put on my thumb"}, {"id": "f1", "type": "textarea", "label": "What that person does to help"}, {"id": "f2", "type": "textarea", "label": "A helper for another finger"}, {"id": "f3", "type": "textarea", "label": "Who I would go to first if I felt upset"}]'::jsonb, array['support', 'children', 'art']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('stop-and-think-traffic-light-craft', 'Stop and Think Traffic Light Craft', 'kids'::resource_kind, 'Children make a traffic light to remember stop, think, then go.', 'Use it to give a child a simple picture for pausing before acting.', array['Children']::text[], '25 minutes', 'The child colors a red, yellow and green light and writes or draws what they do at each. Red means stop, yellow means think of choices, and green means try one. The parent practices it with a pretend problem and then points it out at home in calm moments.', '[{"id": "f0", "type": "textarea", "label": "What I do at red"}, {"id": "f1", "type": "textarea", "label": "A choice I can think of at yellow"}, {"id": "f2", "type": "textarea", "label": "What I try at green"}, {"id": "f3", "type": "textarea", "label": "A time I could use my light"}]'::jsonb, array['regulation', 'behavior', 'children']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('kindness-coupons-making-activity', 'Kindness Coupons Making Activity', 'kids'::resource_kind, 'Children design coupons to give others as small acts of kindness.', 'Use it to help a child practice noticing and giving small acts of kindness.', array['Children']::text[], '25 minutes', 'The child designs three coupons, such as a hug, a drawing or help with a chore, and decides who receives each. The parent takes part by receiving one and saying how it felt. It works well for children who are more used to hearing correction than praise.', '[{"id": "f0", "type": "textarea", "label": "A coupon I made"}, {"id": "f1", "type": "textarea", "label": "Who it is for"}, {"id": "f2", "type": "textarea", "label": "How I think they will feel"}, {"id": "f3", "type": "textarea", "label": "Another kind thing I could do"}]'::jsonb, array['kindness', 'gratitude', 'play']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('feelings-charades-game', 'Feelings Charades Game', 'game'::resource_kind, 'A group game in which players act out feelings and others guess.', 'Use it to help a group practice reading and naming feelings through movement.', array['Groups']::text[], '20 minutes', 'Players take turns drawing a feeling card and acting it without words. The rest guess and say what in the body or face gave it away. Rotate so quiet players are not put on the spot. Debrief which feelings were easy to spot and which were similar.', '[{"id": "f0", "type": "textarea", "label": "A feeling that was easy to act out"}, {"id": "f1", "type": "textarea", "label": "A feeling that was hard to tell apart"}, {"id": "f2", "type": "textarea", "label": "Where I feel one of these in my body"}, {"id": "f3", "type": "textarea", "label": "What I learned about reading others"}]'::jsonb, array['emotion recognition', 'group', 'play']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('values-auction-game', 'Values Auction Game', 'game'::resource_kind, 'Players get play money to bid on values, finding out what they would give up for what.', 'Use it to help players find which values they will spend on when they cannot have everything.', array['Groups']::text[], '30 minutes', 'Give each player the same amount of play money and a list of values to bid on. There are more values than anyone can buy. Afterward ask what they chose, what they let go and how it felt. There are no right buys. Keep the mood light.', '[{"id": "f0", "type": "textarea", "label": "A value I bid the most on"}, {"id": "f1", "type": "textarea", "label": "A value I let go and how that felt"}, {"id": "f2", "type": "textarea", "label": "Something that surprised me about my bids"}, {"id": "f3", "type": "textarea", "label": "One way I could act on my top value this week"}]'::jsonb, array['values', 'group', 'decisions']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('skill-spinner-game', 'Skill Spinner Game', 'game'::resource_kind, 'Players spin for a coping skill and describe when they could use it.', 'Use it to help players link a skill to a real situation in their own lives.', array['Groups']::text[], '20 minutes', 'Make a spinner or use a die with skills written on each side. Players spin, name the skill, and describe a moment they could use it. Others add ideas. Debrief which skills felt like a fit and which felt awkward.', '[{"id": "f0", "type": "textarea", "label": "The skill I landed on"}, {"id": "f1", "type": "textarea", "label": "A time I could use it"}, {"id": "f2", "type": "textarea", "label": "What might get in the way"}, {"id": "f3", "type": "textarea", "label": "A skill I want to try this week"}]'::jsonb, array['skills', 'coping skills', 'group']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('strengths-bingo-game', 'Strengths Bingo Game', 'game'::resource_kind, 'A bingo card of strengths that players mark when they see them in others.', 'Use it to help a group notice and name strengths in each other.', array['Groups']::text[], '25 minutes', 'Each card lists strengths in the squares. During a group activity, players mark a square when they notice a strength in someone else and say who. Debrief by reading squares aloud. Make sure everyone receives at least one mark.', '[{"id": "f0", "type": "textarea", "label": "A strength someone noticed in me"}, {"id": "f1", "type": "textarea", "label": "A strength I noticed in someone else"}, {"id": "f2", "type": "textarea", "label": "A strength I did not expect to be noticed"}, {"id": "f3", "type": "textarea", "label": "How it felt to hear it"}]'::jsonb, array['strengths', 'group', 'positive psychology']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('two-truths-and-a-value-game', 'Two Truths and a Value Game', 'game'::resource_kind, 'Players share two facts and a value about themselves and the others guess which is the value.', 'Use it to help group members share a little about themselves and what matters to them.', array['Groups']::text[], '20 minutes', 'Each player says two facts and one value. Others guess the value and say why. Then the player says why it matters. It works as a warm-up for a new group. Keep the level of sharing up to each person.', '[{"id": "f0", "type": "textarea", "label": "My value"}, {"id": "f1", "type": "textarea", "label": "Why it matters to me"}, {"id": "f2", "type": "textarea", "label": "What others guessed"}, {"id": "f3", "type": "textarea", "label": "Something I learned about someone else"}]'::jsonb, array['icebreaker', 'values', 'group']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('five-senses-grounding-menu', 'Five Senses Grounding Menu', 'worksheet'::resource_kind, 'A menu of sensory grounding options a client picks from and rates.', 'Use it to help a client find grounding options that suit them before they are needed.', array['Adults']::text[], '20 minutes', 'Try each sense in session at a low level of distress and ask the client to rate how much each one helps. Keep the client''s top three on a card. Nothing here asks for details of what happened; the work is about staying present and pacing.', '[{"id": "f0", "type": "textarea", "label": "Something I can see that helps me feel here"}, {"id": "f1", "type": "textarea", "label": "Something I can touch or hold"}, {"id": "f2", "type": "textarea", "label": "A sound or smell that steadies me"}, {"id": "f3", "type": "textarea", "label": "My top three, in order"}, {"id": "f4", "type": "textarea", "label": "Where I will keep this list"}]'::jsonb, array['PTSD and trauma', 'planning']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('helpful-and-unhelpful-coping-after-trauma-sort', 'Helpful and Unhelpful Coping After Trauma Sort', 'cbt'::resource_kind, 'A sort of coping habits into those that help now and those that cost more later.', 'Use it to help a client look at how their coping habits work for them over time.', array['Adults']::text[], '25 minutes', 'Ask the client to list what they do when reminders show up, without describing the event. Sort the list together by short-term relief and longer-term cost. Avoid judgment; every habit was doing a job. Choose one to build on and one to try shrinking.', '[{"id": "f0", "type": "textarea", "label": "Things I do when a reminder shows up"}, {"id": "f1", "type": "textarea", "label": "What each one gives me right away"}, {"id": "f2", "type": "textarea", "label": "What each one costs me later"}, {"id": "f3", "type": "textarea", "label": "One I want to build on"}, {"id": "f4", "type": "textarea", "label": "One I want to try changing slowly"}]'::jsonb, array['PTSD and trauma', 'core CBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('distress-tolerance-crisis-kit-planner', 'Distress Tolerance Crisis Kit Planner', 'dbt'::resource_kind, 'A planner for assembling a kit of skills and contacts for high-distress moments.', 'Use it to help a client prepare a set of options to reach for when distress spikes.', array['Adults']::text[], '25 minutes', 'Build the kit in session while the client is steady. Include body-based skills, a distraction, a soothing item and two contacts. Add 988 (call or text) as an option for any moment of danger, and complete this in session rather than as homework.', '[{"id": "f0", "type": "textarea", "label": "A body skill I can use"}, {"id": "f1", "type": "textarea", "label": "A distraction I like"}, {"id": "f2", "type": "textarea", "label": "Something soothing I can hold or listen to"}, {"id": "f3", "type": "textarea", "label": "Two people I can contact"}, {"id": "f4", "type": "textarea", "label": "If I am in danger, I will call or text 988 and I will put it here"}]'::jsonb, array['PTSD and trauma', 'core DBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('values-after-hard-times-sheet', 'Values After Hard Times Sheet', 'act'::resource_kind, 'A sheet for naming what still matters to a client and one small step toward it.', 'Use it to help a client reconnect with what matters at a pace that feels safe.', array['Adults']::text[], '20 minutes', 'Keep the focus on the present and the future, not on what happened. Ask what the client used to care about and what they still do. Choose one small step and check it is safe and paced. If the client shifts toward telling the event, gently return to the sheet.', '[{"id": "f0", "type": "textarea", "label": "Something that still matters to me"}, {"id": "f1", "type": "textarea", "label": "Something I used to enjoy"}, {"id": "f2", "type": "textarea", "label": "A small step toward it this week"}, {"id": "f3", "type": "textarea", "label": "What could help me keep the pace gentle"}]'::jsonb, array['PTSD and trauma', 'core ACT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('partner-reminder-response-plan', 'Partner Reminder Response Plan', 'couples'::resource_kind, 'A plan where partners agree how one will help when the other is reminded of something hard.', 'Use it to help partners agree ahead of time how to respond when reminders arise.', array['Couples']::text[], '30 minutes', 'The partner who is affected says what helps and what does not, and the other listens and repeats it back. Agree on a signal, a way of being close or apart, and a check-in afterward. Neither partner is asked to describe the event.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps when I am reminded"}, {"id": "f1", "type": "textarea", "label": "Partner A: what does not help"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I will do"}, {"id": "f3", "type": "textarea", "label": "Our signal"}, {"id": "f4", "type": "textarea", "label": "How we will check in afterward"}]'::jsonb, array['PTSD and trauma', 'couples']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('anxiety-prediction-and-outcome-comparison', 'Anxiety Prediction and Outcome Comparison', 'worksheet'::resource_kind, 'A sheet for writing a fear, how likely it seems, and what happened.', 'Use it to help a client compare their anxious predictions with real outcomes.', array['Adults']::text[], 'Five minutes daily for a week', 'The client writes down what they expect will happen before a situation and what did happen after. Review the sheet for the times the prediction was off and the times it held. Treat the second with the same curiosity, and plan for those.', '[{"id": "f0", "type": "textarea", "label": "What I expect will happen"}, {"id": "f1", "type": "textarea", "label": "How sure I am (0 to 100)"}, {"id": "f2", "type": "textarea", "label": "What actually happened"}, {"id": "f3", "type": "textarea", "label": "What I learned"}, {"id": "f4", "type": "textarea", "label": "How I coped with the hard parts"}]'::jsonb, array['anxiety', 'planning']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('probability-and-coping-scale-sheet', 'Probability and Coping Scale Sheet', 'cbt'::resource_kind, 'A sheet that separates how likely a feared event is from how well the client could cope.', 'Use it to help a client see that likelihood and coping ability are two separate questions.', array['Adults']::text[], '20 minutes', 'Ask for the fear, then for a number on how likely it is and a second number on how well the client could cope. Coping is usually underrated. Then list ways they have coped with hard things before. Keep the mood curious.', '[{"id": "f0", "type": "textarea", "label": "The feared outcome"}, {"id": "f1", "type": "textarea", "label": "How likely it seems (0 to 100)"}, {"id": "f2", "type": "textarea", "label": "What I would do if it happened"}, {"id": "f3", "type": "textarea", "label": "Times I coped with something hard before"}, {"id": "f4", "type": "textarea", "label": "How I feel about coping now"}]'::jsonb, array['anxiety', 'core CBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('cope-ahead-rehearsal-sheet', 'Cope Ahead Rehearsal Sheet', 'dbt'::resource_kind, 'A rehearsal sheet for imagining a hard event and the skills the client will use.', 'Use it to help a client rehearse skills for an upcoming situation that worries them.', array['Adults']::text[], '25 minutes', 'Ask the client to describe the situation, pick two skills and picture using them from start to finish. Rehearse aloud where you can. Talk about what might go wrong and how they would handle it. This builds readiness, it does not promise a result.', '[{"id": "f0", "type": "textarea", "label": "The situation coming up"}, {"id": "f1", "type": "textarea", "label": "What I expect to be hard"}, {"id": "f2", "type": "textarea", "label": "Two skills I will use"}, {"id": "f3", "type": "textarea", "label": "How I will picture myself using them"}, {"id": "f4", "type": "textarea", "label": "What I will say to myself"}]'::jsonb, array['anxiety', 'core DBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('anxiety-welcome-and-carry-practice', 'Anxiety Welcome and Carry Practice', 'act'::resource_kind, 'A practice of letting anxiety come along while doing something that matters.', 'Use it to help a client do a valued thing while allowing anxiety to be present.', array['Adults']::text[], '20 minutes', 'Ask the client to choose a valued activity that anxiety tends to interrupt. Practice noticing the anxiety, naming it, and taking the next step anyway. The measure is the action, not the anxiety level. Debrief what it was like to carry it.', '[{"id": "f0", "type": "textarea", "label": "The valued thing I want to do"}, {"id": "f1", "type": "textarea", "label": "What anxiety says about it"}, {"id": "f2", "type": "textarea", "label": "Where I feel it in my body"}, {"id": "f3", "type": "textarea", "label": "What I did with it along for the ride"}]'::jsonb, array['anxiety', 'core ACT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('worry-monster-puppet-craft', 'Worry Monster Puppet Craft', 'kids'::resource_kind, 'Children make a puppet of their worry and decide how to talk back to it.', 'Use it to give a child a playful way to separate from their worry and talk to it.', array['Children']::text[], '30 minutes', 'The child makes a puppet from a sock or paper bag and gives it a name. Together they decide what the worry monster says and what the child says back. The parent watches and learns a phrase to use at home. Keep it silly and small.', '[{"id": "f0", "type": "textarea", "label": "My worry monster''s name"}, {"id": "f1", "type": "textarea", "label": "What it says to me"}, {"id": "f2", "type": "textarea", "label": "What I say back"}, {"id": "f3", "type": "textarea", "label": "Who can help me when it gets loud"}]'::jsonb, array['anxiety', 'children']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('tiny-steps-momentum-sheet', 'Tiny Steps Momentum Sheet', 'worksheet'::resource_kind, 'A sheet for breaking one hard task into steps small enough to start.', 'Use it to help a client shrink a task until the first step feels doable.', array['Adults']::text[], '20 minutes', 'Choose one task the client keeps avoiding and break it down until the first step takes under five minutes. Agree when they will do it. Celebrate the start, not the finish. If energy is very low, make the step even smaller.', '[{"id": "f0", "type": "textarea", "label": "The task I am avoiding"}, {"id": "f1", "type": "textarea", "label": "The smallest first step"}, {"id": "f2", "type": "textarea", "label": "When I will do it"}, {"id": "f3", "type": "textarea", "label": "What could get in the way"}, {"id": "f4", "type": "textarea", "label": "How I will reward myself"}]'::jsonb, array['depression', 'planning']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('mood-linked-thought-sorting-sheet', 'Mood-Linked Thought Sorting Sheet', 'cbt'::resource_kind, 'A sheet that sorts low-mood thoughts into facts, opinions and predictions.', 'Use it to help a client tell apart what is known from what the mood is saying.', array['Adults']::text[], '20 minutes', 'Ask the client to write three thoughts that show up when their mood dips. Then sort each as a fact, an opinion or a prediction. Do not argue with the thoughts; help the client look at them. Choose one to test in the coming week.', '[{"id": "f0", "type": "textarea", "label": "A thought that comes up when my mood is low"}, {"id": "f1", "type": "textarea", "label": "Is it a fact, an opinion or a prediction?"}, {"id": "f2", "type": "textarea", "label": "What supports it and what does not"}, {"id": "f3", "type": "textarea", "label": "A test I could try this week"}]'::jsonb, array['depression', 'core CBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('build-positive-experiences-planner', 'Build Positive Experiences Planner', 'dbt'::resource_kind, 'A planner for adding pleasant events now and working toward long-term goals.', 'Use it to help a client add small positive experiences to their days.', array['Adults']::text[], '25 minutes', 'Have the client pick one short pleasant event a day for the week and one step toward a longer-term goal. Talk through what might get in the way. When mood is low, pleasure can be muted; ask the client to notice small differences, not big ones.', '[{"id": "f0", "type": "textarea", "label": "Pleasant events I will try"}, {"id": "f1", "type": "textarea", "label": "When I will do each"}, {"id": "f2", "type": "textarea", "label": "A longer-term goal I care about"}, {"id": "f3", "type": "textarea", "label": "One step this week"}, {"id": "f4", "type": "textarea", "label": "What I noticed after"}]'::jsonb, array['depression', 'core DBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('partner-encouragement-plan', 'Partner Encouragement Plan', 'couples'::resource_kind, 'A plan where partners agree how to encourage each other on low days without pressure.', 'Use it to help partners agree how to offer support on low days.', array['Couples']::text[], '30 minutes', 'The partner who has low days says what kind of encouragement helps and what feels like pressure. The other partner says what they can offer and what they need for themselves. Agree on a phrase and a small shared activity. Check back on it in a couple of weeks.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps on a low day"}, {"id": "f1", "type": "textarea", "label": "Partner A: what feels like pressure"}, {"id": "f2", "type": "textarea", "label": "Partner B: what I can offer"}, {"id": "f3", "type": "textarea", "label": "Partner B: what I need too"}, {"id": "f4", "type": "textarea", "label": "A small thing we can do together"}]'::jsonb, array['depression', 'couples']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('low-energy-menu-game', 'Low Energy Menu Game', 'game'::resource_kind, 'A group game for choosing tiny activities for a day from a menu by rolling a die.', 'Use it to help group members find small, doable activities for low-energy days.', array['Groups']::text[], '20 minutes', 'Prepare a menu of small activities numbered one to six. Players roll, read the activity, and say how they could fit it into the next day. Debrief which ideas felt possible. Keep the mood light, and let players trade if a roll does not suit them.', '[{"id": "f0", "type": "textarea", "label": "The activity I rolled"}, {"id": "f1", "type": "textarea", "label": "How I could fit it into my day"}, {"id": "f2", "type": "textarea", "label": "What might get in the way"}, {"id": "f3", "type": "textarea", "label": "An activity I would add to the menu"}]'::jsonb, array['depression', 'play']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('external-reminders-setup-sheet', 'External Reminders Setup Sheet', 'worksheet'::resource_kind, 'A sheet for placing reminders where the client will meet them.', 'Use it to help a client put reminders in places they cannot miss.', array['Adults']::text[], '20 minutes', 'Ask the client to choose three recurring tasks that slip and place a visible cue for each in the spot where it would matter. Try them for a week and adjust. Encourage bright, physical cues over lists that live out of sight.', '[{"id": "f0", "type": "textarea", "label": "A task that slips"}, {"id": "f1", "type": "textarea", "label": "Where I will put a cue for it"}, {"id": "f2", "type": "textarea", "label": "What the cue will look like"}, {"id": "f3", "type": "textarea", "label": "How I will know it works"}]'::jsonb, array['ADHD', 'planning']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('distraction-pattern-log', 'Distraction Pattern Log', 'cbt'::resource_kind, 'A log of what pulls attention off a task and what brought it back.', 'Use it to help a client see what pulls their attention and what returns it.', array['Adults']::text[], 'Ten minutes daily for a week', 'The client notes three distractions a day, what they were doing, and what got them back on track. Look for repeated pulls and repeated returns. Plan one change to the setting. Avoid framing it as a lack of effort.', '[{"id": "f0", "type": "textarea", "label": "What I was doing"}, {"id": "f1", "type": "textarea", "label": "What pulled my attention"}, {"id": "f2", "type": "textarea", "label": "How long it took me to return"}, {"id": "f3", "type": "textarea", "label": "What helped me return"}, {"id": "f4", "type": "textarea", "label": "A change I could make to my space"}]'::jsonb, array['ADHD', 'core CBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('values-based-focus-anchor-card', 'Values-Based Focus Anchor Card', 'act'::resource_kind, 'A card linking one small task to a value so it feels worth starting.', 'Use it to help a client connect a dull task to something they care about.', array['Adults']::text[], '15 minutes', 'Pick one routine task and ask what it serves. Write the value on a card that sits by the task. The card does not create motivation; it gives the client a reason to start. Review how it landed in the next session.', '[{"id": "f0", "type": "textarea", "label": "A task I keep putting off"}, {"id": "f1", "type": "textarea", "label": "What it serves that I care about"}, {"id": "f2", "type": "textarea", "label": "A phrase to put on the card"}, {"id": "f3", "type": "textarea", "label": "Where I will place the card"}]'::jsonb, array['ADHD', 'core ACT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('household-systems-agreement', 'Household Systems Agreement', 'couples'::resource_kind, 'A page where partners divide tasks and choose visible systems for them.', 'Use it to help partners agree who does which tasks and what will remind them.', array['Couples']::text[], '30 minutes', 'List the shared tasks, divide them by preference and time, and choose a visible system for each, such as a whiteboard or shared calendar. Talk about how to raise misses without blame. Revisit in two weeks and change what is not working.', '[{"id": "f0", "type": "textarea", "label": "Partner A: tasks I will take"}, {"id": "f1", "type": "textarea", "label": "Partner B: tasks I will take"}, {"id": "f2", "type": "textarea", "label": "The system we will use"}, {"id": "f3", "type": "textarea", "label": "How we will remind each other kindly"}, {"id": "f4", "type": "textarea", "label": "When we will review"}]'::jsonb, array['ADHD', 'couples']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('morning-routine-picture-chart-craft', 'Morning Routine Picture Chart Craft', 'kids'::resource_kind, 'Children draw and arrange the steps of a routine into a chart.', 'Use it to help a child follow a routine they made themselves with pictures.', array['Children']::text[], '30 minutes', 'The child draws each step of a morning or bedtime routine and arranges them in order with the parent. The parent agrees to cue with the chart, not with repeated reminders. Post the chart at the child''s eye level and review after a week.', '[{"id": "f0", "type": "textarea", "label": "Step one I drew"}, {"id": "f1", "type": "textarea", "label": "Step two I drew"}, {"id": "f2", "type": "textarea", "label": "The step I find hardest"}, {"id": "f3", "type": "textarea", "label": "How my parent will help"}]'::jsonb, array['ADHD', 'children']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('substance-use-ambivalence-sheet', 'Substance Use Ambivalence Sheet', 'worksheet'::resource_kind, 'A sheet for laying out both sides of a client''s feelings about their substance use.', 'Use it to help a client explore mixed feelings about their substance use in their own words.', array['Adults']::text[], '25 minutes', 'Use a motivational interviewing stance and let the client voice both sides without arguing for change. Ask what they like about it and what worries them. Summarize back both sides. Avoid labels; describe the pattern and the client''s goals.', '[{"id": "f0", "type": "textarea", "label": "What I get from substance use"}, {"id": "f1", "type": "textarea", "label": "What worries me about it"}, {"id": "f2", "type": "textarea", "label": "What I would like my life to look like"}, {"id": "f3", "type": "textarea", "label": "One thing I am willing to consider"}]'::jsonb, array['addiction', 'planning']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('chain-of-events-before-a-lapse-sheet', 'Chain of Events Before a Lapse Sheet', 'cbt'::resource_kind, 'A sheet that traces the steps that led up to a lapse in a nonjudgmental way.', 'Use it to help a client see the steps before a lapse and where a different choice was possible.', array['Adults']::text[], '25 minutes', 'Walk back from a lapse step by step: situation, thoughts, feelings, urges and choices. Look for points where something else was possible. Keep it curious, not shaming. Pick one point to plan a different move for next time.', '[{"id": "f0", "type": "textarea", "label": "What was going on before"}, {"id": "f1", "type": "textarea", "label": "Thoughts and feelings I had"}, {"id": "f2", "type": "textarea", "label": "The urge, and how strong it was"}, {"id": "f3", "type": "textarea", "label": "A point where I could have done something else"}, {"id": "f4", "type": "textarea", "label": "My plan for next time"}]'::jsonb, array['addiction', 'core CBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('urge-surfing-wave-log', 'Urge Surfing Wave Log', 'dbt'::resource_kind, 'A log for riding an urge like a wave and noting how it rose and fell.', 'Use it to help a client watch an urge rise and fall without acting on it.', array['Adults']::text[], 'Ten minutes each time an urge shows up', 'Teach the client to notice the urge, rate it, breathe and watch it change every few minutes. Many clients are surprised that urges crest and fade. Keep a log to review together. If the urges are tied to safety concerns, use your own plan.', '[{"id": "f0", "type": "textarea", "label": "What set off the urge"}, {"id": "f1", "type": "textarea", "label": "The urge at the start (0 to 10)"}, {"id": "f2", "type": "textarea", "label": "What I did while riding it"}, {"id": "f3", "type": "textarea", "label": "The urge after ten minutes (0 to 10)"}, {"id": "f4", "type": "textarea", "label": "What I noticed"}]'::jsonb, array['addiction', 'core DBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('partner-support-and-boundaries-plan', 'Partner Support and Boundaries Plan', 'couples'::resource_kind, 'A plan where partners state what support helps and what limits each needs.', 'Use it to help partners agree on how to support recovery while keeping their own limits.', array['Couples']::text[], '30 minutes', 'The partner working on substance use says what support helps. The other says what they can offer and what limits they need to keep. Agree on how to handle a lapse and how to check in. Avoid turning it into monitoring or blame.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what support helps"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I can offer"}, {"id": "f2", "type": "textarea", "label": "Partner B: limits I need to keep"}, {"id": "f3", "type": "textarea", "label": "How we will handle a lapse"}, {"id": "f4", "type": "textarea", "label": "How we will check in"}]'::jsonb, array['addiction', 'couples']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('refusal-skills-role-play-game', 'Refusal Skills Role Play Game', 'game'::resource_kind, 'Players draw scenarios and practice saying no to substance use offers.', 'Use it to help players practice saying no in a range of realistic situations.', array['Groups']::text[], '30 minutes', 'Players draw a scenario card and practice a refusal while another plays the person offering. Try different styles: firm, humorous, leaving. Debrief what felt natural and what did not. Keep the offers realistic but not pressuring.', '[{"id": "f0", "type": "textarea", "label": "The scenario I drew"}, {"id": "f1", "type": "textarea", "label": "What I said"}, {"id": "f2", "type": "textarea", "label": "What felt natural"}, {"id": "f3", "type": "textarea", "label": "What I would add next time"}]'::jsonb, array['addiction', 'play']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('anger-trigger-and-body-cue-log', 'Anger Trigger and Body Cue Log', 'worksheet'::resource_kind, 'A log linking what sets off anger with the early body signs.', 'Use it to help a client catch anger earlier through their body signals.', array['Adults']::text[], 'Five minutes after each event for two weeks', 'Ask the client to record what set off the anger, what they noticed in their body first and what they did. Review for the earliest cue. That cue is the one to build a pause on. Do not use the log to make a case against them.', '[{"id": "f0", "type": "textarea", "label": "What set it off"}, {"id": "f1", "type": "textarea", "label": "The first body sign"}, {"id": "f2", "type": "textarea", "label": "What I did next"}, {"id": "f3", "type": "textarea", "label": "How I would have liked to respond"}]'::jsonb, array['anger management', 'planning']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('anger-thoughts-rewrite-sheet', 'Anger Thoughts Rewrite Sheet', 'cbt'::resource_kind, 'A sheet for spotting hot thoughts that feed anger and finding fairer ones.', 'Use it to help a client look at the thoughts that fuel their anger.', array['Adults']::text[], '20 minutes', 'Ask for a recent moment and the thought behind it, such as "they did that on purpose". Look for words like always and never. Write a fairer version that fits the facts. The goal is not to talk the client out of the feeling but to widen the view.', '[{"id": "f0", "type": "textarea", "label": "What happened"}, {"id": "f1", "type": "textarea", "label": "The thought that made me angrier"}, {"id": "f2", "type": "textarea", "label": "Another way to see it"}, {"id": "f3", "type": "textarea", "label": "How I feel after the second view"}]'::jsonb, array['anger management', 'core CBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('emotion-mind-time-out-plan', 'Emotion Mind Time-Out Plan', 'dbt'::resource_kind, 'A plan for how a client steps away, cools down and returns when anger is high.', 'Use it to help a client leave a heated moment and return in a calmer state.', array['Adults']::text[], '25 minutes', 'Agree on how the client will say they need a break, where they will go, what they will do to settle and when they will come back. Practice the exit line. Make sure a time to return is part of it so the break does not become avoidance.', '[{"id": "f0", "type": "textarea", "label": "What I will say to take a break"}, {"id": "f1", "type": "textarea", "label": "Where I will go"}, {"id": "f2", "type": "textarea", "label": "What I will do to settle"}, {"id": "f3", "type": "textarea", "label": "When I will come back"}]'::jsonb, array['anger management', 'core DBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('anger-under-the-surface-practice', 'Anger Under the Surface Practice', 'act'::resource_kind, 'A practice of looking beneath anger for the hurt or need it protects.', 'Use it to help a client notice what sits under their anger.', array['Adults']::text[], '20 minutes', 'Ask what the client felt just before the anger arrived. Often there is hurt, worry or a need. Do not push; offer options if the client cannot name it. Then ask what they would want to do that reflects the need, not just the anger.', '[{"id": "f0", "type": "textarea", "label": "A time I was angry"}, {"id": "f1", "type": "textarea", "label": "What I felt just before"}, {"id": "f2", "type": "textarea", "label": "What I might have needed"}, {"id": "f3", "type": "textarea", "label": "What I could do about that need"}]'::jsonb, array['anger management', 'core ACT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('volcano-cooling-experiment-activity', 'Volcano Cooling Experiment Activity', 'kids'::resource_kind, 'Children make a small volcano and think about cooling down before it erupts.', 'Use it to give a child a picture for anger building and ways to release pressure safely.', array['Children']::text[], '30 minutes', 'Make a baking soda volcano outdoors or in a tray. Talk about what builds pressure in the child and what lets it out safely, such as running, squeezing a pillow or asking for help. The parent joins and picks a cooling move of their own.', '[{"id": "f0", "type": "textarea", "label": "What makes my volcano build up"}, {"id": "f1", "type": "textarea", "label": "How I know it is about to erupt"}, {"id": "f2", "type": "textarea", "label": "A safe way to let it out"}, {"id": "f3", "type": "textarea", "label": "Who can help me cool down"}]'::jsonb, array['anger management', 'children']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('doubt-loop-mapping-sheet', 'Doubt Loop Mapping Sheet', 'worksheet'::resource_kind, 'A sheet for mapping the doubt, the urge to check and the relief that follows.', 'Use it to help a client see the loop between doubt, checking and short-lived relief.', array['Adults']::text[], '25 minutes', 'Ask the client to map a recent loop: the thought, the feeling, what they did, and what happened after. Draw the arrows so they can see how relief returns doubt. Keep the focus on the pattern, not the content of the thought.', '[{"id": "f0", "type": "textarea", "label": "The doubt that showed up"}, {"id": "f1", "type": "textarea", "label": "What I felt"}, {"id": "f2", "type": "textarea", "label": "What I did to feel sure"}, {"id": "f3", "type": "textarea", "label": "How long the relief lasted"}, {"id": "f4", "type": "textarea", "label": "What the loop cost me"}]'::jsonb, array['OCD', 'planning']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('response-delay-step-ladder', 'Response Delay Step Ladder', 'cbt'::resource_kind, 'A ladder of steps for waiting longer before responding to an urge.', 'Use it to help a client practice waiting a little longer each time an urge arises.', array['Adults']::text[], '25 minutes', 'Build a ladder of urges from easier to harder and agree on how long to wait for each. Start low and do it together in session. Encourage the client to notice how anxiety rises and falls while they wait. Adjust the rungs as they go.', '[{"id": "f0", "type": "textarea", "label": "An urge on my ladder"}, {"id": "f1", "type": "textarea", "label": "How long I will wait"}, {"id": "f2", "type": "textarea", "label": "What I will do while waiting"}, {"id": "f3", "type": "textarea", "label": "What I noticed after"}]'::jsonb, array['OCD', 'core CBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('unwanted-thoughts-as-noise-practice', 'Unwanted Thoughts as Noise Practice', 'act'::resource_kind, 'A defusion practice of hearing intrusive thoughts as background noise.', 'Use it to help a client hold intrusive thoughts more lightly.', array['Adults']::text[], '15 minutes', 'Ask the client to picture a radio playing in the background and name the thoughts as "the radio is playing that one again". The thought is not a command and does not need an answer. Practice it in session and then between sessions.', '[{"id": "f0", "type": "textarea", "label": "A thought that came again"}, {"id": "f1", "type": "textarea", "label": "How I named it"}, {"id": "f2", "type": "textarea", "label": "What I did instead of answering it"}, {"id": "f3", "type": "textarea", "label": "What I noticed"}]'::jsonb, array['OCD', 'core ACT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('reassurance-pattern-agreement', 'Reassurance Pattern Agreement', 'couples'::resource_kind, 'A page where partners agree how to respond when reassurance is asked for.', 'Use it to help partners agree how to respond kindly without feeding reassurance.', array['Couples']::text[], '30 minutes', 'The partner with the thoughts explains how reassurance feels in the moment and what happens after. The other says how it feels to be asked. Agree on a warm, brief response together, such as acknowledging the feeling without answering the doubt.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how reassurance feels to me"}, {"id": "f1", "type": "textarea", "label": "Partner B: how it feels to be asked"}, {"id": "f2", "type": "textarea", "label": "A kind phrase we can use"}, {"id": "f3", "type": "textarea", "label": "What Partner A will do instead"}]'::jsonb, array['OCD', 'couples']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('maybe-game', 'Maybe Game', 'game'::resource_kind, 'Players practice saying maybe to uncertain questions and staying with it.', 'Use it to help players practice living with a question that stays open.', array['Groups']::text[], '20 minutes', 'Players draw an uncertain question card, answer only with "maybe", and stay quiet for thirty seconds. The group then shares what came up. Keep the questions light. Debrief how it felt to leave the question open.', '[{"id": "f0", "type": "textarea", "label": "The question I drew"}, {"id": "f1", "type": "textarea", "label": "What I felt when I said maybe"}, {"id": "f2", "type": "textarea", "label": "What I did to stay with it"}, {"id": "f3", "type": "textarea", "label": "What I noticed in the group"}]'::jsonb, array['OCD', 'play']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('panic-wave-rating-sheet', 'Panic Wave Rating Sheet', 'worksheet'::resource_kind, 'A sheet for rating a panic wave every minute to see it crest and fall.', 'Use it to help a client see that a panic wave rises, peaks and passes.', array['Adults']::text[], 'Ten minutes after an event', 'After an episode, the client reconstructs the wave minute by minute with a number from 0 to 10. Look at the shape together. Ask what they did at the peak and what they noticed as it eased. The chart is a record of the experience, not a measure of anything else.', '[{"id": "f0", "type": "textarea", "label": "Where I was and what led up to it"}, {"id": "f1", "type": "textarea", "label": "My peak (0 to 10) and the minute it came"}, {"id": "f2", "type": "textarea", "label": "What I did at the peak"}, {"id": "f3", "type": "textarea", "label": "What I noticed as it eased"}]'::jsonb, array['panic attacks', 'planning']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('sensation-reinterpretation-cards', 'Sensation Reinterpretation Cards', 'cbt'::resource_kind, 'Cards pairing a scary body sensation with a plain, non-alarming explanation.', 'Use it to help a client practice a calmer reading of body sensations.', array['Adults']::text[], '20 minutes', 'Ask the client to write a sensation on one side of a card and the alarming meaning they give it. On the other side, write a plainer explanation, such as a fast heart rate from adrenaline. Rehearse reading them aloud. Check any physical concerns with the client''s doctor.', '[{"id": "f0", "type": "textarea", "label": "A sensation that scares me"}, {"id": "f1", "type": "textarea", "label": "What I tell myself it means"}, {"id": "f2", "type": "textarea", "label": "A plainer explanation"}, {"id": "f3", "type": "textarea", "label": "What I can do while it passes"}]'::jsonb, array['panic attacks', 'core CBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('paced-breathing-and-cold-water-skill-card', 'Paced Breathing and Cold Water Skill Card', 'dbt'::resource_kind, 'A card for two quick skills that slow the body during a panic wave.', 'Use it to help a client practice quick body skills before panic arrives.', array['Adults']::text[], '20 minutes', 'Practice paced breathing and cool water on the face in session. Check for any health reasons to skip the cold water skill. Emphasize that these skills lower arousal, and the aim is to stay in the situation, not escape it.', '[{"id": "f0", "type": "textarea", "label": "How my body felt before"}, {"id": "f1", "type": "textarea", "label": "Which skill I tried"}, {"id": "f2", "type": "textarea", "label": "How my body felt after"}, {"id": "f3", "type": "textarea", "label": "When I will practice it this week"}]'::jsonb, array['panic attacks', 'core DBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('panic-passenger-practice', 'Panic Passenger Practice', 'act'::resource_kind, 'A practice of letting panic sit in the car while the client keeps driving toward a valued place.', 'Use it to help a client act on a value while allowing panic to come along.', array['Adults']::text[], '20 minutes', 'Use the passenger image: panic is on board, loud and pushy, but it is not at the wheel. Have the client choose a valued place or activity that panic has limited. Plan a small step and what they will say to the passenger.', '[{"id": "f0", "type": "textarea", "label": "Somewhere I want to go"}, {"id": "f1", "type": "textarea", "label": "What panic says about going"}, {"id": "f2", "type": "textarea", "label": "What I say back"}, {"id": "f3", "type": "textarea", "label": "One small step this week"}]'::jsonb, array['panic attacks', 'core ACT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('sensation-sort-game', 'Sensation Sort Game', 'game'::resource_kind, 'Players sort body sensations into those that come with panic and those that come with everyday things.', 'Use it to help players see how ordinary many body sensations are.', array['Groups']::text[], '20 minutes', 'Prepare cards with sensations. Players sort them into piles and discuss the overlap with everyday situations such as climbing stairs or drinking coffee. Debrief what surprised them. Point out that all sensations can be uncomfortable without being dangerous.', '[{"id": "f0", "type": "textarea", "label": "A sensation I sorted"}, {"id": "f1", "type": "textarea", "label": "Where else I feel it"}, {"id": "f2", "type": "textarea", "label": "What surprised me"}, {"id": "f3", "type": "textarea", "label": "What I will remember next time"}]'::jsonb, array['panic attacks', 'play']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('positive-attention-log', 'Positive Attention Log', 'worksheet'::resource_kind, 'A log for parents to record moments of attention on behavior they want to see more of.', 'Use it to help a parent notice and name behavior they want to grow.', array['Adults']::text[], 'Five minutes daily for a week', 'Ask the parent to write down one thing per day they noticed the child doing well and what they said. Keep the praise specific and immediate. Discuss when it is hard to notice. Start with something small so the habit sticks.', '[{"id": "f0", "type": "textarea", "label": "What I noticed my child doing well"}, {"id": "f1", "type": "textarea", "label": "What I said"}, {"id": "f2", "type": "textarea", "label": "How my child responded"}, {"id": "f3", "type": "textarea", "label": "What I want to notice tomorrow"}]'::jsonb, array['parenting', 'planning']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('parent-thoughts-in-hard-moments-sheet', 'Parent Thoughts in Hard Moments Sheet', 'cbt'::resource_kind, 'A sheet for spotting thoughts that raise a parent''s temper and finding fairer ones.', 'Use it to help a parent look at the thoughts that shape how they react.', array['Adults']::text[], '20 minutes', 'Ask for a recent moment, the thought, and what the parent did. Common thoughts include "they are doing this on purpose". Write a fairer alternative and try it aloud. Be kind: parents are usually tired and doing their best.', '[{"id": "f0", "type": "textarea", "label": "The moment that was hard"}, {"id": "f1", "type": "textarea", "label": "The thought I had"}, {"id": "f2", "type": "textarea", "label": "A fairer thought"}, {"id": "f3", "type": "textarea", "label": "What I could do next time"}]'::jsonb, array['parenting', 'core CBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('validate-then-limit-practice-card', 'Validate Then Limit Practice Card', 'dbt'::resource_kind, 'A card for acknowledging a child''s feeling and then holding the limit.', 'Use it to help a parent validate a feeling and hold a limit in the same breath.', array['Adults']::text[], '20 minutes', 'Give the parent a pattern: name the feeling, name the limit, offer a choice. Role-play with an example, with the clinician playing the child. Notice when the parent slips into lecturing. Practice at least three lines together.', '[{"id": "f0", "type": "textarea", "label": "A limit I need to hold"}, {"id": "f1", "type": "textarea", "label": "The feeling behind my child''s reaction"}, {"id": "f2", "type": "textarea", "label": "What I will say to validate it"}, {"id": "f3", "type": "textarea", "label": "What I will say to hold the limit"}]'::jsonb, array['parenting', 'core DBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('co-parent-consistency-agreement', 'Co-Parent Consistency Agreement', 'couples'::resource_kind, 'A page where co-parents agree on a few shared responses to common situations.', 'Use it to help co-parents agree on the same response to a few common situations.', array['Couples']::text[], '30 minutes', 'Choose three recurring situations and have each parent say how they handle them. Look for a shared response and write it down. Where they differ, note the difference and revisit it. Keep it to a short list they can remember.', '[{"id": "f0", "type": "textarea", "label": "Situation one and what we will do"}, {"id": "f1", "type": "textarea", "label": "Situation two and what we will do"}, {"id": "f2", "type": "textarea", "label": "Situation three and what we will do"}, {"id": "f3", "type": "textarea", "label": "How we will back each other up"}, {"id": "f4", "type": "textarea", "label": "When we will review"}]'::jsonb, array['parenting', 'couples']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('family-rules-poster-craft', 'Family Rules Poster Craft', 'kids'::resource_kind, 'Children and parents make a poster of a few rules stated in positive words.', 'Use it to help a family make and post a few clear rules together.', array['Children']::text[], '30 minutes', 'The child and parent decide on three rules stated as what to do, such as "we use kind words". The child decorates the poster. The parent agrees to point to it rather than nag. Review in a couple of weeks.', '[{"id": "f0", "type": "textarea", "label": "A rule I picked"}, {"id": "f1", "type": "textarea", "label": "What it looks like"}, {"id": "f2", "type": "textarea", "label": "How I decorated it"}, {"id": "f3", "type": "textarea", "label": "What happens when we follow it"}]'::jsonb, array['parenting', 'children']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('postpartum-week-rhythm-planner', 'Postpartum Week Rhythm Planner', 'worksheet'::resource_kind, 'A planner that lays out sleep, feeding, rest and help across a typical week.', 'Use it to help a new parent see where rest and help can fit into a week.', array['Adults']::text[], '25 minutes', 'Map a typical week and mark when the parent rests, when others help and when the day is hardest. Look for the gap. Ask who could take one task. The planner is about support and realism, not doing more.', '[{"id": "f0", "type": "textarea", "label": "The hardest part of my day"}, {"id": "f1", "type": "textarea", "label": "When I can rest"}, {"id": "f2", "type": "textarea", "label": "Who could help and with what"}, {"id": "f3", "type": "textarea", "label": "One change I will try this week"}]'::jsonb, array['perinatal and postpartum', 'planning']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('new-parent-worry-sorting-sheet', 'New Parent Worry Sorting Sheet', 'cbt'::resource_kind, 'A sheet for sorting worries into those to act on and those to let pass.', 'Use it to help a new parent sort worries into ones they can act on and ones they cannot.', array['Adults']::text[], '20 minutes', 'Ask for a list of worries. Sort them into actionable and not. For actionable, write one step. For the rest, practice a brief acknowledging phrase. If a worry involves harm to self or baby, follow your own risk process and note 988 (call or text) in session.', '[{"id": "f0", "type": "textarea", "label": "My worries right now"}, {"id": "f1", "type": "textarea", "label": "Ones I can act on"}, {"id": "f2", "type": "textarea", "label": "One step for each"}, {"id": "f3", "type": "textarea", "label": "How I will let the others pass"}, {"id": "f4", "type": "textarea", "label": "If I feel unsafe I will call or text 988"}]'::jsonb, array['perinatal and postpartum', 'core CBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('self-care-basics-please-check', 'Self-Care Basics PLEASE Check', 'dbt'::resource_kind, 'A check of sleep, eating, movement and health basics adapted for a new parent.', 'Use it to help a new parent see which basics are slipping and what small support could help.', array['Adults']::text[], '20 minutes', 'Go through the basics with the parent in a curious way. Focus on small, achievable steps and on getting help with them. Avoid making it another list of shoulds. Ask what a good-enough day looks like right now.', '[{"id": "f0", "type": "textarea", "label": "Sleep right now"}, {"id": "f1", "type": "textarea", "label": "Eating and drinking"}, {"id": "f2", "type": "textarea", "label": "Movement and fresh air"}, {"id": "f3", "type": "textarea", "label": "Health appointments"}, {"id": "f4", "type": "textarea", "label": "One basic I will protect this week"}]'::jsonb, array['perinatal and postpartum', 'core DBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('night-shift-fairness-sheet', 'Night Shift Fairness Sheet', 'couples'::resource_kind, 'A sheet for partners to talk about how nights are shared and how each feels about it.', 'Use it to help partners talk about how night care is shared and how each one feels.', array['Couples']::text[], '30 minutes', 'Each partner says how nights are going and what they need. Look at the plan on paper and try one change. Watch for resentment and for one partner carrying more; invite a plain conversation rather than a scorecard.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how nights feel for me"}, {"id": "f1", "type": "textarea", "label": "Partner B: how nights feel for me"}, {"id": "f2", "type": "textarea", "label": "A change we will try"}, {"id": "f3", "type": "textarea", "label": "How we will check on it"}]'::jsonb, array['perinatal and postpartum', 'couples']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('big-sibling-helper-badge-craft', 'Big Sibling Helper Badge Craft', 'kids'::resource_kind, 'A craft for an older child to make a helper badge and learn ways to help.', 'Use it to help an older child feel included and useful with a new baby.', array['Children']::text[], '25 minutes', 'The child decorates a badge and lists ways they can help, such as choosing a book for the baby. The parent sets aside a few minutes of one-on-one time each day. Name feelings openly, including jealousy.', '[{"id": "f0", "type": "textarea", "label": "Ways I can help with the baby"}, {"id": "f1", "type": "textarea", "label": "How I feel about the baby"}, {"id": "f2", "type": "textarea", "label": "What I want to do with my parent"}, {"id": "f3", "type": "textarea", "label": "Who I can tell when I feel left out"}]'::jsonb, array['perinatal and postpartum', 'children']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('achievements-and-effort-record', 'Achievements and Effort Record', 'worksheet'::resource_kind, 'A record of things a client did and the effort behind them, not just outcomes.', 'Use it to help a client see effort and action as worth counting.', array['Adults']::text[], 'Ten minutes weekly', 'Ask the client to write three things they did this week and what it took. Count effort as well as results. Some clients dismiss entries; ask what they would say if a friend wrote them. Keep a running list for review.', '[{"id": "f0", "type": "textarea", "label": "Something I did this week"}, {"id": "f1", "type": "textarea", "label": "What it took from me"}, {"id": "f2", "type": "textarea", "label": "What it says about me"}, {"id": "f3", "type": "textarea", "label": "Something I want to add to my list"}]'::jsonb, array['self-esteem', 'planning']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('core-belief-reframe-card', 'Core Belief Reframe Card', 'cbt'::resource_kind, 'A card with an old core belief on one side and a more balanced belief on the other.', 'Use it to help a client practice a more balanced belief alongside the old one.', array['Adults']::text[], '25 minutes', 'Work from a belief the client already knows. Collect evidence that does not fit it, and write a balanced version they can partly believe. Rate belief in each. Expect the old belief to still feel strong; the new one is built over time.', '[{"id": "f0", "type": "textarea", "label": "The old belief and how strongly I hold it (0 to 100)"}, {"id": "f1", "type": "textarea", "label": "Evidence that does not fit it"}, {"id": "f2", "type": "textarea", "label": "A more balanced belief"}, {"id": "f3", "type": "textarea", "label": "How much I believe it now (0 to 100)"}]'::jsonb, array['self-esteem', 'core CBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('build-mastery-and-pride-sheet', 'Build Mastery and Pride Sheet', 'dbt'::resource_kind, 'A sheet for choosing one thing to get better at and noting each small win.', 'Use it to help a client build a sense of competence through small, repeated wins.', array['Adults']::text[], '20 minutes', 'Choose a skill that is achievable and chosen by the client. Set a small daily step. Record what they did and what they felt. Talk about the difference between pride and perfection.', '[{"id": "f0", "type": "textarea", "label": "The skill I chose"}, {"id": "f1", "type": "textarea", "label": "My step today"}, {"id": "f2", "type": "textarea", "label": "What I did"}, {"id": "f3", "type": "textarea", "label": "What I felt"}]'::jsonb, array['self-esteem', 'core DBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('self-as-story-rewrite-practice', 'Self as Story Rewrite Practice', 'act'::resource_kind, 'A practice of noticing the story a client tells about themselves and holding it lightly.', 'Use it to help a client see their self-story as one version, not the whole truth.', array['Adults']::text[], '20 minutes', 'Ask the client to give the story a name, such as "the one who always fails". Then ask what else is true about them. Practice saying "I am having the story that". Do not try to replace it with a shinier one; loosen it.', '[{"id": "f0", "type": "textarea", "label": "The name of my story"}, {"id": "f1", "type": "textarea", "label": "What it tells me about myself"}, {"id": "f2", "type": "textarea", "label": "What else is true about me"}, {"id": "f3", "type": "textarea", "label": "What I want to do next"}]'::jsonb, array['self-esteem', 'core ACT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('compliment-catch-game', 'Compliment Catch Game', 'game'::resource_kind, 'Players toss a ball and share a genuine strength they see in the catcher.', 'Use it to help a group practice offering and receiving sincere strengths.', array['Groups']::text[], '20 minutes', 'Players stand in a circle and toss a soft ball. The thrower says a specific strength they see in the catcher, and the catcher says thank you. Coach players to receive without deflecting. Debrief how it felt to hear and to say.', '[{"id": "f0", "type": "textarea", "label": "A strength someone named in me"}, {"id": "f1", "type": "textarea", "label": "How it felt to hear it"}, {"id": "f2", "type": "textarea", "label": "A strength I named in someone"}, {"id": "f3", "type": "textarea", "label": "What I will take with me"}]'::jsonb, array['self-esteem', 'play']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('social-situations-difficulty-ladder', 'Social Situations Difficulty Ladder', 'worksheet'::resource_kind, 'A ladder ranking social situations from easier to harder.', 'Use it to help a client build an ordered list of situations to work through.', array['Adults']::text[], '25 minutes', 'Ask the client to list situations and rate difficulty from 0 to 100. Order them and pick one at the lower end to try first. Make the steps specific and small. Adjust as they go; the ladder is a working document.', '[{"id": "f0", "type": "textarea", "label": "Situations I avoid or dread"}, {"id": "f1", "type": "textarea", "label": "Difficulty rating for each"}, {"id": "f2", "type": "textarea", "label": "The one I will try first"}, {"id": "f3", "type": "textarea", "label": "When and how I will do it"}]'::jsonb, array['social anxiety', 'planning']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('self-focus-and-attention-experiment', 'Self-Focus and Attention Experiment', 'cbt'::resource_kind, 'An experiment comparing attention on self with attention on the other person.', 'Use it to help a client test how shifting attention changes their experience of a conversation.', array['Adults']::text[], '25 minutes', 'In one conversation, the client focuses on their own performance; in another, on the other person and the environment. Compare notes on anxiety and on how the conversation went. Discuss what they observed, not what they should conclude.', '[{"id": "f0", "type": "textarea", "label": "Anxiety when I focused on myself (0 to 100)"}, {"id": "f1", "type": "textarea", "label": "Anxiety when I focused on them (0 to 100)"}, {"id": "f2", "type": "textarea", "label": "What I noticed about the conversation"}, {"id": "f3", "type": "textarea", "label": "What I will try next"}]'::jsonb, array['social anxiety', 'core CBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('anxious-and-present-practice', 'Anxious and Present Practice', 'act'::resource_kind, 'A practice of staying in a social moment with anxiety present.', 'Use it to help a client stay engaged in a social moment while feeling anxious.', array['Adults']::text[], '20 minutes', 'Choose one small social moment. The client notes anxiety, names it, and turns attention to one detail of the conversation. Measure success by staying engaged, not by feeling calm. Debrief what it was like.', '[{"id": "f0", "type": "textarea", "label": "The social moment"}, {"id": "f1", "type": "textarea", "label": "What anxiety said"}, {"id": "f2", "type": "textarea", "label": "What I turned my attention to"}, {"id": "f3", "type": "textarea", "label": "What I did next"}]'::jsonb, array['social anxiety', 'core ACT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('social-event-teamwork-plan', 'Social Event Teamwork Plan', 'couples'::resource_kind, 'A plan for how partners support each other at a social event.', 'Use it to help partners agree how to support each other at a social event.', array['Couples']::text[], '25 minutes', 'The partner who is anxious says what helps, such as a check-in signal or an agreed time to leave. The other says what they need, too. Avoid using the plan to avoid events; use it to make them possible.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what helps at an event"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I need at an event"}, {"id": "f2", "type": "textarea", "label": "Our signal"}, {"id": "f3", "type": "textarea", "label": "How long we plan to stay"}, {"id": "f4", "type": "textarea", "label": "How we will debrief"}]'::jsonb, array['social anxiety', 'couples']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('brave-hello-practice-game', 'Brave Hello Practice Game', 'kids'::resource_kind, 'Children practice greeting with puppets and then with a real person.', 'Use it to help a child practice saying hello in steps that feel manageable.', array['Children']::text[], '25 minutes', 'Start with puppets or stuffed animals and move to the parent and then to the clinician. Praise attempts, not perfect hellos. The parent practices waiting and not speaking for the child. Pick a very small real-world hello for the week.', '[{"id": "f0", "type": "textarea", "label": "Who I said hello to"}, {"id": "f1", "type": "textarea", "label": "How I said it"}, {"id": "f2", "type": "textarea", "label": "How it felt"}, {"id": "f3", "type": "textarea", "label": "Who I will say hello to next"}]'::jsonb, array['social anxiety', 'children']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('grief-anniversary-planning-sheet', 'Grief Anniversary Planning Sheet', 'worksheet'::resource_kind, 'A sheet for planning how to spend a hard date, with support and choice.', 'Use it to help a client plan ahead for an anniversary or hard date.', array['Adults']::text[], '25 minutes', 'Ask what the client wants the day to hold: company, quiet, ritual. Plan who they might ask for support. Include a backup plan. There is no right way to grieve; the plan is meant to give them choices, not to fix the day.', '[{"id": "f0", "type": "textarea", "label": "The date and what it means"}, {"id": "f1", "type": "textarea", "label": "What I want the day to hold"}, {"id": "f2", "type": "textarea", "label": "Who I would like near"}, {"id": "f3", "type": "textarea", "label": "A backup if it gets too much"}]'::jsonb, array['grief and loss', 'planning']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('grief-thoughts-notebook', 'Grief Thoughts Notebook', 'cbt'::resource_kind, 'A notebook page for noticing thoughts and the feelings that come with them.', 'Use it to help a client notice the thoughts that shape waves of grief.', array['Adults']::text[], 'Ten minutes daily for a week', 'The client writes what they were thinking during a wave and how it felt. Some thoughts are just true and painful; others include self-blame or predictions that can be examined. Do not push to reframe grief itself.', '[{"id": "f0", "type": "textarea", "label": "The moment"}, {"id": "f1", "type": "textarea", "label": "The thought I had"}, {"id": "f2", "type": "textarea", "label": "How I felt"}, {"id": "f3", "type": "textarea", "label": "A kinder thought, if one fits"}]'::jsonb, array['grief and loss', 'core CBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('radical-acceptance-of-the-loss-practice', 'Radical Acceptance of the Loss Practice', 'dbt'::resource_kind, 'A practice of turning the mind toward what cannot be changed, gently and in small steps.', 'Use it to help a client practice small moments of accepting what has happened.', array['Adults']::text[], '20 minutes', 'Explain that acceptance is not approval or being over it. Practice a short phrase such as "this happened, and I am here". Notice the pull to argue with reality and the relief of setting it down for a moment.', '[{"id": "f0", "type": "textarea", "label": "What I am struggling to accept"}, {"id": "f1", "type": "textarea", "label": "What I say when I fight it"}, {"id": "f2", "type": "textarea", "label": "What I could say instead"}, {"id": "f3", "type": "textarea", "label": "How my body felt"}]'::jsonb, array['grief and loss', 'core DBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('grieving-differently-conversation-guide', 'Grieving Differently Conversation Guide', 'couples'::resource_kind, 'A guide for partners to talk about how each of them grieves.', 'Use it to help partners talk about how differently each of them grieves.', array['Couples']::text[], '30 minutes', 'Each partner says how they grieve, what helps and what they need from the other. Normalize different paces and styles. Agree on one way to be close in grief and one way to give each other space.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I grieve"}, {"id": "f1", "type": "textarea", "label": "Partner B: how I grieve"}, {"id": "f2", "type": "textarea", "label": "What we each need"}, {"id": "f3", "type": "textarea", "label": "A way to be close"}, {"id": "f4", "type": "textarea", "label": "A way to give space"}]'::jsonb, array['grief and loss', 'couples']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('memory-jar-craft', 'Memory Jar Craft', 'kids'::resource_kind, 'Children fill a jar with drawn or written memories of someone they miss.', 'Use it to give a child a hands-on way to remember someone they lost.', array['Children']::text[], '30 minutes', 'The child decorates a jar and adds slips with drawings or words of memories. The parent adds one too. Explain that feelings come and go. Follow the child''s lead on what to share.', '[{"id": "f0", "type": "textarea", "label": "A memory I put in the jar"}, {"id": "f1", "type": "textarea", "label": "What I miss"}, {"id": "f2", "type": "textarea", "label": "How I feel when I think about it"}, {"id": "f3", "type": "textarea", "label": "Who I can share it with"}]'::jsonb, array['grief and loss', 'children']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('recurring-argument-map', 'Recurring Argument Map', 'worksheet'::resource_kind, 'A map of one recurring argument: trigger, positions, feelings and what each needs.', 'Use it to help a client or partners see the shape of an argument that keeps returning.', array['Adults']::text[], '25 minutes', 'Draw the last argument as a sequence: trigger, first words, reactions, ending. Ask what each person felt and needed under the words. Look at where it could have turned. Keep it about the pattern rather than who was right.', '[{"id": "f0", "type": "textarea", "label": "What started it"}, {"id": "f1", "type": "textarea", "label": "What I said and did"}, {"id": "f2", "type": "textarea", "label": "What I was feeling underneath"}, {"id": "f3", "type": "textarea", "label": "What I needed"}, {"id": "f4", "type": "textarea", "label": "Where it could have turned"}]'::jsonb, array['relationship issues', 'planning']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('relationship-interpretation-check', 'Relationship Interpretation Check', 'cbt'::resource_kind, 'A sheet for checking a first reading of a partner''s behavior against other explanations.', 'Use it to help a client test a first reading of a partner''s behavior against other possibilities.', array['Adults']::text[], '20 minutes', 'Ask for a recent moment and the story the client told. List two other explanations and one thing they could ask. Rate belief in each. It does not excuse harm, so leave room for it if the pattern is real.', '[{"id": "f0", "type": "textarea", "label": "What my partner did"}, {"id": "f1", "type": "textarea", "label": "What I told myself it meant"}, {"id": "f2", "type": "textarea", "label": "Two other possible explanations"}, {"id": "f3", "type": "textarea", "label": "A question I could ask"}]'::jsonb, array['relationship issues', 'core CBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('give-and-fast-skills-practice', 'GIVE and FAST Skills Practice', 'dbt'::resource_kind, 'A practice sheet for using GIVE to keep the relationship and FAST to keep self-respect.', 'Use it to help a client balance keeping a relationship with keeping their self-respect.', array['Adults']::text[], '25 minutes', 'Pick a real interaction and plan it using GIVE (gentle, interested, validate, easy manner) and FAST (fair, apologies, stick to values, truthful). Role-play a first line. Look at which matters most in this situation.', '[{"id": "f0", "type": "textarea", "label": "The interaction"}, {"id": "f1", "type": "textarea", "label": "What I will do for GIVE"}, {"id": "f2", "type": "textarea", "label": "What I will do for FAST"}, {"id": "f3", "type": "textarea", "label": "What matters most here"}]'::jsonb, array['relationship issues', 'core DBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('repair-attempt-phrases-card', 'Repair Attempt Phrases Card', 'couples'::resource_kind, 'A card of phrases partners can use to stop an argument from escalating.', 'Use it to help partners choose repair phrases they can say mid-argument.', array['Couples']::text[], '25 minutes', 'Each partner picks phrases that would help them and agrees to accept the other''s attempts. Practice saying them in session. Notice how each one hears them. Attempts fail when they sound sarcastic, so check the tone.', '[{"id": "f0", "type": "textarea", "label": "Partner A: phrases that would help me"}, {"id": "f1", "type": "textarea", "label": "Partner B: phrases that would help me"}, {"id": "f2", "type": "textarea", "label": "How we will signal a repair"}, {"id": "f3", "type": "textarea", "label": "How we will accept it"}]'::jsonb, array['relationship issues', 'couples']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('perspective-swap-game', 'Perspective Swap Game', 'game'::resource_kind, 'Players argue a fictional disagreement from each side, then swap.', 'Use it to help players practice seeing a disagreement from the other person''s side.', array['Groups']::text[], '25 minutes', 'Pairs get a fictional disagreement and argue one side for two minutes, then swap sides. Debrief what each felt, and what they understood about the other side. Keep it fictional so nobody has to argue their own conflict.', '[{"id": "f0", "type": "textarea", "label": "The side I argued first"}, {"id": "f1", "type": "textarea", "label": "What I understood when I swapped"}, {"id": "f2", "type": "textarea", "label": "What I would say differently"}, {"id": "f3", "type": "textarea", "label": "What I will take into my own relationships"}]'::jsonb, array['relationship issues', 'play']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('personal-safety-circle-sheet', 'Personal Safety Circle Sheet', 'worksheet'::resource_kind, 'A sheet for mapping who is close, who is safe and who is not.', 'Use it to help a client map who feels safe and who does not.', array['Adults']::text[], '25 minutes', 'Draw circles and have the client place people by how safe they feel. Nothing about events is needed. Discuss support and how to protect time and space. If risk to safety appears, follow your own process and your reporting duties.', '[{"id": "f0", "type": "textarea", "label": "People in my safest circle"}, {"id": "f1", "type": "textarea", "label": "People I keep at a distance"}, {"id": "f2", "type": "textarea", "label": "What makes someone feel safe"}, {"id": "f3", "type": "textarea", "label": "One way I can protect my space"}]'::jsonb, array['sexual abuse', 'planning']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('self-blame-thought-check', 'Self-Blame Thought Check', 'cbt'::resource_kind, 'A sheet for looking at self-blaming thoughts in the present, without retelling events.', 'Use it to help a client notice self-blame and question it with kindness.', array['Adults']::text[], '20 minutes', 'Ask for the current thought, such as "it was my fault", without any account of what happened. Look at what a responsible person would say and who holds responsibility. Go slowly, and stop if the client is distressed.', '[{"id": "f0", "type": "textarea", "label": "A self-blaming thought that shows up"}, {"id": "f1", "type": "textarea", "label": "What I would say to a friend with that thought"}, {"id": "f2", "type": "textarea", "label": "A kinder thought"}, {"id": "f3", "type": "textarea", "label": "How I feel when I read it"}]'::jsonb, array['sexual abuse', 'core CBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('self-soothing-kit-builder', 'Self-Soothing Kit Builder', 'dbt'::resource_kind, 'A builder for a kit of comforting items for each sense.', 'Use it to help a client collect comforting items for hard moments.', array['Adults']::text[], '25 minutes', 'Choose one item per sense and keep them in a box. Try each in session. The kit is about comfort and pacing. If distress is high, use grounding first. Include 988 (call or text) on the list of supports and complete it in session.', '[{"id": "f0", "type": "textarea", "label": "Something to see"}, {"id": "f1", "type": "textarea", "label": "Something to hear"}, {"id": "f2", "type": "textarea", "label": "Something to touch"}, {"id": "f3", "type": "textarea", "label": "Something to smell or taste"}, {"id": "f4", "type": "textarea", "label": "A support I can contact, including 988"}]'::jsonb, array['sexual abuse', 'core DBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('intimacy-pacing-and-consent-agreement', 'Intimacy Pacing and Consent Agreement', 'couples'::resource_kind, 'A page where partners agree how to go slowly and check in about closeness.', 'Use it to help partners agree on pacing, choice and check-ins about closeness.', array['Couples']::text[], '30 minutes', 'The partner who is a survivor says what pace and signals feel right, and the other listens and repeats. Both are free to say stop at any point. Agree on a signal and a way to reconnect afterward. No detail of the past is needed.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what pace feels right"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I will do to support it"}, {"id": "f2", "type": "textarea", "label": "Our stop signal"}, {"id": "f3", "type": "textarea", "label": "How we will reconnect afterward"}]'::jsonb, array['sexual abuse', 'couples']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('body-boundaries-traffic-light-craft', 'Body Boundaries Traffic Light Craft', 'kids'::resource_kind, 'Children make a traffic light to sort touches and situations they like and do not like.', 'Use it to help a child practice saying no and telling a trusted adult.', array['Children']::text[], '25 minutes', 'The child colors a traffic light and places examples such as high fives and hugs on green, yellow and red. The parent shows they will listen if the child tells them anything. Remember your reporting duties if a child discloses.', '[{"id": "f0", "type": "textarea", "label": "A touch I like"}, {"id": "f1", "type": "textarea", "label": "A touch I do not like"}, {"id": "f2", "type": "textarea", "label": "What I can say"}, {"id": "f3", "type": "textarea", "label": "Who I can tell if something feels wrong"}]'::jsonb, array['sexual abuse', 'children']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('coping-skill-trial-and-review-sheet', 'Coping Skill Trial and Review Sheet', 'worksheet'::resource_kind, 'A sheet for trying a skill in real life and reviewing how it worked.', 'Use it to help a client test a skill in real life and note what happened.', array['Adults']::text[], '15 minutes', 'Pick one skill and ask the client when they will try it. Afterward, they rate how it felt and what helped or got in the way. Keep the sheet simple so it gets used.', '[{"id": "f0", "type": "textarea", "label": "The skill"}, {"id": "f1", "type": "textarea", "label": "When I tried it"}, {"id": "f2", "type": "textarea", "label": "What happened"}, {"id": "f3", "type": "textarea", "label": "What helped or got in the way"}]'::jsonb, array['coping skills', 'planning']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('coping-thoughts-card-builder', 'Coping Thoughts Card Builder', 'cbt'::resource_kind, 'A builder for cards holding helpful coping statements the client believes.', 'Use it to help a client write coping statements they find credible.', array['Adults']::text[], '20 minutes', 'Ask the client to write statements in their own voice, such as "this is hard and I have handled hard things". Reject statements they do not believe. Rehearse them and place the cards where they will be seen.', '[{"id": "f0", "type": "textarea", "label": "A hard moment I face"}, {"id": "f1", "type": "textarea", "label": "A statement I would believe in that moment"}, {"id": "f2", "type": "textarea", "label": "How much I believe it (0 to 100)"}, {"id": "f3", "type": "textarea", "label": "Where I will keep the card"}]'::jsonb, array['coping skills', 'core CBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('accepts-distraction-menu', 'ACCEPTS Distraction Menu', 'dbt'::resource_kind, 'A menu of distraction ideas sorted by activities, contributing, comparisons, emotions, push away, thoughts and sensations.', 'Use it to help a client build a personal list of distractions for high-distress times.', array['Adults']::text[], '25 minutes', 'Walk through each letter and ask the client to write one idea that would work for them. Emphasize that distraction is a short-term skill for getting through a peak, not for avoiding everything. Star three.', '[{"id": "f0", "type": "textarea", "label": "An activity"}, {"id": "f1", "type": "textarea", "label": "Something I could do for someone else"}, {"id": "f2", "type": "textarea", "label": "An emotion I could invite instead"}, {"id": "f3", "type": "textarea", "label": "A sensation I could use"}, {"id": "f4", "type": "textarea", "label": "My three favorites"}]'::jsonb, array['coping skills', 'core DBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('coping-that-fits-my-values-sort', 'Coping That Fits My Values Sort', 'act'::resource_kind, 'A sort of coping habits by whether they move a client toward or away from what matters.', 'Use it to help a client sort coping habits by the direction they move them.', array['Adults']::text[], '20 minutes', 'Write coping habits on cards. The client sorts them into toward and away from what they value. Many habits do both; note the mix. Choose one to do more and one to do less.', '[{"id": "f0", "type": "textarea", "label": "A coping habit I use"}, {"id": "f1", "type": "textarea", "label": "Does it move me toward or away from what I value?"}, {"id": "f2", "type": "textarea", "label": "What it gives me"}, {"id": "f3", "type": "textarea", "label": "One I want to do more of"}]'::jsonb, array['coping skills', 'core ACT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('coping-skills-spinner-craft', 'Coping Skills Spinner Craft', 'kids'::resource_kind, 'Children make a spinner with coping skills and spin to try one.', 'Use it to give a child a playful way to pick and practice a coping skill.', array['Children']::text[], '30 minutes', 'The child decorates a paper plate spinner with six skills, such as breathing, drawing, or asking for a hug. Spin and try the one it lands on. The parent tries one, too. Post it somewhere handy.', '[{"id": "f0", "type": "textarea", "label": "A skill on my spinner"}, {"id": "f1", "type": "textarea", "label": "When I could use it"}, {"id": "f2", "type": "textarea", "label": "How it felt"}, {"id": "f3", "type": "textarea", "label": "A skill I would add"}]'::jsonb, array['coping skills', 'children']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('fear-rating-and-avoidance-record', 'Fear Rating and Avoidance Record', 'worksheet'::resource_kind, 'A record of fear ratings and avoided situations over time.', 'Use it to help a client track fear levels and what they avoid, so planning is concrete.', array['Adults']::text[], 'Five minutes daily for a week', 'The client records each time they met or avoided a feared thing, their fear from 0 to 100, and what they did. Use it as a baseline for planning steps. Review it without judgment, since avoidance makes sense.', '[{"id": "f0", "type": "textarea", "label": "The feared thing and the situation"}, {"id": "f1", "type": "textarea", "label": "My fear (0 to 100)"}, {"id": "f2", "type": "textarea", "label": "What I did"}, {"id": "f3", "type": "textarea", "label": "What I avoided and what it cost me"}]'::jsonb, array['phobias', 'planning']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('feared-outcome-checking-sheet', 'Feared Outcome Checking Sheet', 'cbt'::resource_kind, 'A sheet for writing what the client expects and checking it against what happened.', 'Use it to help a client compare the feared outcome with what happened in an exposure step.', array['Adults']::text[], '20 minutes', 'Before a step, the client writes the feared outcome and how sure they are. After, they write what happened. Look at the gap. If the outcome was unpleasant but manageable, note the coping. Repeat with the next step.', '[{"id": "f0", "type": "textarea", "label": "The step I am about to take"}, {"id": "f1", "type": "textarea", "label": "What I expect will happen"}, {"id": "f2", "type": "textarea", "label": "What happened"}, {"id": "f3", "type": "textarea", "label": "What I learned"}]'::jsonb, array['phobias', 'core CBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('fear-ladder-willing-hands-practice', 'Fear Ladder Willing Hands Practice', 'dbt'::resource_kind, 'A practice of standing with open hands and willing posture while facing a feared step.', 'Use it to help a client approach a feared step with a willing body posture.', array['Adults']::text[], '20 minutes', 'Teach willing hands (palms up, relaxed) and a half-smile as body cues that support approach. Practice with a mild step in session. Ask what changes in the body. This is a cue, not a guarantee.', '[{"id": "f0", "type": "textarea", "label": "The step I am facing"}, {"id": "f1", "type": "textarea", "label": "What my body does when I face it"}, {"id": "f2", "type": "textarea", "label": "What willing hands felt like"}, {"id": "f3", "type": "textarea", "label": "What I will try next"}]'::jsonb, array['phobias', 'core DBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('exposure-coach-role-agreement', 'Exposure Coach Role Agreement', 'couples'::resource_kind, 'A page where a partner agrees to support without pushing or rescuing.', 'Use it to help partners agree how one coaches the other through exposure steps.', array['Couples']::text[], '25 minutes', 'The partner facing the fear says what support looks like and how they want to be encouraged. The partner says what they can and cannot do. Agree on what happens if the step is too much. Coaching is not rescuing or pushing.', '[{"id": "f0", "type": "textarea", "label": "Partner A: how I want to be supported"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I can do"}, {"id": "f2", "type": "textarea", "label": "What we will say when it gets hard"}, {"id": "f3", "type": "textarea", "label": "How we will end a step"}]'::jsonb, array['phobias', 'couples']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('brave-step-dice-game', 'Brave Step Dice Game', 'game'::resource_kind, 'Players roll for a size of brave step and describe one they could take.', 'Use it to help players think of brave steps of different sizes for their own fears.', array['Groups']::text[], '20 minutes', 'Roll a die to pick a size from one (tiny) to six (big). Each player names a step of that size for a fear of their own. Group members add ideas. Debrief what felt possible.', '[{"id": "f0", "type": "textarea", "label": "The step size I rolled"}, {"id": "f1", "type": "textarea", "label": "A step of that size for me"}, {"id": "f2", "type": "textarea", "label": "What might get in the way"}, {"id": "f3", "type": "textarea", "label": "When I could try it"}]'::jsonb, array['phobias', 'play']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('body-image-values-sort', 'Body Image Values Sort', 'worksheet'::resource_kind, 'A sort of what a client wants their relationship with their body to stand for.', 'Use it to help a client name values for how they relate to their body.', array['Adults']::text[], '20 minutes', 'Offer values such as respect, curiosity, ease and care, and have the client choose three. Ask what an action based on each would look like on an ordinary day. Keep the focus on how they relate to themselves and steer clear of anything about size or shape.', '[{"id": "f0", "type": "textarea", "label": "Three values for how I treat my body"}, {"id": "f1", "type": "textarea", "label": "An action that fits each"}, {"id": "f2", "type": "textarea", "label": "A moment I did it this week"}, {"id": "f3", "type": "textarea", "label": "A barrier to it"}]'::jsonb, array['body image', 'planning']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('appearance-thoughts-record', 'Appearance Thoughts Record', 'cbt'::resource_kind, 'A record of thoughts about appearance and the situations that bring them up.', 'Use it to help a client see the thoughts and situations that raise body worries.', array['Adults']::text[], '20 minutes', 'Ask for a situation, the thought and the mood. Look at the rules and comparisons hiding in the thought. Write a balanced alternative that does not depend on appearance. Steer clear of measuring or rating the body.', '[{"id": "f0", "type": "textarea", "label": "The situation"}, {"id": "f1", "type": "textarea", "label": "The thought about my appearance"}, {"id": "f2", "type": "textarea", "label": "How I felt"}, {"id": "f3", "type": "textarea", "label": "A balanced thought that is not about looks"}]'::jsonb, array['body image', 'core CBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('kind-body-care-plan', 'Kind Body Care Plan', 'dbt'::resource_kind, 'A plan for caring for the body out of respect, not punishment.', 'Use it to help a client choose acts of care for their body that come from kindness.', array['Adults']::text[], '20 minutes', 'Ask the client to list ways of caring for their body, such as rest, stretching, a warm bath. Choose two for the week. Notice whether they come from care or from a should. Adjust the list to fit.', '[{"id": "f0", "type": "textarea", "label": "A way I can care for my body"}, {"id": "f1", "type": "textarea", "label": "Why it matters to me"}, {"id": "f2", "type": "textarea", "label": "When I will do it"}, {"id": "f3", "type": "textarea", "label": "How it felt"}]'::jsonb, array['body image', 'core DBT']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('partner-affirmation-exchange', 'Partner Affirmation Exchange', 'couples'::resource_kind, 'A page where partners share what they appreciate about each other as whole people.', 'Use it to help partners share appreciation for each other that goes beyond appearance.', array['Couples']::text[], '25 minutes', 'Each partner writes and says three things they appreciate that are not about looks. The listener says thank you without deflecting. Discuss how the other partner hears comments about bodies and agree on ones to skip.', '[{"id": "f0", "type": "textarea", "label": "Partner A: what I appreciate about you"}, {"id": "f1", "type": "textarea", "label": "Partner B: what I appreciate about you"}, {"id": "f2", "type": "textarea", "label": "How it felt to hear"}, {"id": "f3", "type": "textarea", "label": "Comments we agree to skip"}]'::jsonb, array['body image', 'couples']::text[], '2026-09-29T15:00:00+00:00'::timestamptz),
  ('body-neutral-statements-game', 'Body Neutral Statements Game', 'game'::resource_kind, 'Players turn appearance statements into neutral or function-based ones.', 'Use it to help players practice neutral, function-based ways to talk about the body.', array['Groups']::text[], '20 minutes', 'Prepare cards with appearance-focused comments. Players rewrite each into neutral or function-based language such as "my legs carry me". Debrief how it felt. Avoid any statements about size, shape or eating.', '[{"id": "f0", "type": "textarea", "label": "A comment I rewrote"}, {"id": "f1", "type": "textarea", "label": "How I rewrote it"}, {"id": "f2", "type": "textarea", "label": "How the new one felt"}, {"id": "f3", "type": "textarea", "label": "Where I could use it"}]'::jsonb, array['body image', 'play']::text[], '2026-09-29T15:00:00+00:00'::timestamptz)
